 "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 1280, "y": 0}}, {"id": "node-muqbtqz0-6l0b", "data": {"label": "Tính trừu tượng (Abstraction)", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 300, "height": 45}, "position": {"x": 640, "y": 90}}, {"id": "node-muqbtqz0-gnzt", "data": {"label": "Che giấu logic phức tạp, chỉ đưa ra phương thức đơn giản cho bên ngoài gọi, còn xử lý bên trong ntn thì không show ra - sử dụng private keyword cho các phương thức xử lý bên trong", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 183}, "position": {"x": 960, "y": 90}}, {"id": "node-muqbtqz0-2q5c", "data": {"label": "Lợi ích: đơn giản hóa cho user sử dụng và khi có sử code logic bên trong thì không gây ảnh hưởng tới các chỗ gọi tới nó", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 1280, "y": 90}}, {"id": "node-muqbtqz0-kk6w", "data": {"label": "Tính kế thừa (Inheritance)", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 266, "height": 45}, "position": {"x": 640, "y": 180}}, {"id": "node-muqbtqz0-mzlc", "data": {"label": "Class cha sẽ khai báo các phương thức và thuộc tính chung nhất của 1 dạng đối tượng", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 960, "y": 180}}, {"id": "node-muqbtqz0-um13", "data": {"label": "Các class con sẽ kế thừa (sử dụng extends keyword) class cha và có thể thêm các phương thức hoặc thuộc tính riêng của từng loại để phù hợp với nhu cầu sử dụng", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 155}, "position": {"x": 1280, "y": 180}}, {"id": "node-muqbtqz0-xz5g", "data": {"label": "Tính đa hình (Polymorphism)", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 295, "height": 45}, "position": {"x": 640, "y": 270}}, {"id": "node-muqbtqz0-u0ob", "data": {"label": "Class cha khai báo phương thức và thuộc tính dùng chung, nhưng khi các class con kế thừa thì nó có thể ghi đè lên các phương thức và thuộc tính đó để thực thi các nội dung khác nhau", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 183}, "position": {"x": 960, "y": 270}}, {"id": "node-muqbtqz0-yzjn", "data": {"label": "class Employee {\\npublic role = 'Employee';\\ndoWork() {\\nconsole.log([${this.role}] doing work);\\n}\\n}\\nclass Developer extends Employee {\\nrole = 'Developer';\\ndoWork() {\\nconsole.log([${this.role}] Coding);\\n}\\n}\\nclass Tester extends Employee {\\nrole = 'Tester';\\ndoWork() {\\nconsole.log([${this.role}] Testing);\\n}\\n}\\nclass ProjectManager extends Employee {\\nrole = 'Project Manager';\\ndoWork() {\\nconsole.log([${this.role}] Research new feature);\\n}\\n}\\n// let do your works\\nconst works = [\\nnew Developer(),\\nnew Tester(),\\nnew ProjectManager()\\n];\\nworks.forEach((work) => {\\nwork.doWork()\\n});", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 1008}, "position": {"x": 1280, "y": 270}}, {"id": "node-muqbtqz0-q8mn", "data": {"label": "Composition", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 148, "height": 45}, "position": {"x": 320, "y": 360}}, {"id": "node-muqbtqz0-tcwd", "data": {"label": "Nhìn vào ví dụ trong tính đa hình (polymophism), giờ phát sinh ra 1 ông Full-Stack có thể làm tất cả các công việc của Developer, Tester, PM. thì thay vì việc ta phải định nghĩa lại hàm doWork thì ta sẽ lấy luôn các hàm doWork của các nhân viên khác tổng hợp vào là xong", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 238}, "position": {"x": 640, "y": 360}}, {"id": "node-muqbtqz0-xh51", "data": {"label": "class FullStack extends Employee {\\nrole = 'FullStack';\\nprivate developer = new Developer();\\nprivate tester = new Tester();\\nprivate pm = new ProjectManager();\\ndoWork() {\\nthis.developer.doWork();\\nthis.tester.doWork();\\nthis.pm.doWork();\\n}\\n}\\nconst fullstack = new FullStack();\\nfullstack.doWork();", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 430}, "position": {"x": 960, "y": 360}}], "viewport": {"x": 489.1599511599512, "y": 191.4175824175824, "zoom": 0.3400488400488401}}	2026-10-02 02:11:03.131	2026-10-02 02:11:06.169	\N
