en": false, "source": "node-muqbul9r-k6p5", "target": "node-muqbul9r-vwfe"}], "nodes": [{"id": "root", "data": {"label": "MongoDB", "isRoot": true, "collapsed": false, "childCount": 10}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 44}, "position": {"x": 0, "y": 0}}, {"id": "node-muqbul9q-1329", "data": {"label": "MongoDB là một hệ quản trị CSDL dạng tài liệu (document database)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 320, "y": -3105}}, {"id": "node-muqbul9q-gvr7", "data": {"label": "Các mô hình triển khai MongoDB", "isRoot": false, "collapsed": false, "childCount": 3, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 334, "height": 45}, "position": {"x": 320, "y": -2745}}, {"id": "node-muqbul9q-uvr2", "data": {"label": "Standalone", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 45}, "position": {"x": 640, "y": -3015}}, {"id": "node-muqbul9q-uh08", "data": {"label": "chỉ có duy nhất 1 mongoDB server", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 343, "height": 45}, "position": {"x": 960, "y": -3015}}, {"id": "node-muqbul9q-kkdf", "data": {"label": "Replication", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 45}, "position": {"x": 640, "y": -2745}}, {"id": "node-muqbul9q-8qlj", "data": {"label": "có nhiều mongo node (số node nên là số lẻ để tối ưu cho việc bầu trọn primary mới), trong đó có 1 node chính gọi là primary và các node phụ (secondary) sẽ được đồng bộ dữ liệu từ primary", "isRoot": false, "collapsed": false, "childCount": 5, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 183}, "position": {"x": 960, "y": -2745}}, {"id": "node-muqbul9q-cm89", "data": {"label": "Đảm bảo high availability (HA): Khi primary node gặp sự cố, cơ chế Failover được kích hoạt", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 1280, "y": -2925}}, {"id": "node-muqbul9q-eaay", "data": {"label": "Failover (Chuyển đổi dự phòng): Khi primary node gặp sự cố, thì 1 secondary node sẽ lên thay làm primary để đảm bảo tính sẵn sàng của hệ thống", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 155}, "position": {"x": 1280, "y": -2835}}, {"id": "node-muqbul9q-8ghr", "data": {"label": "Read scaling thông qua việc read từ secondary node", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 1280, "y": -2745}}, {"id": "node-muqbul9q-u9re", "data": {"label": "Backup data thông qua việc dữ liệu được đồng bộ từ primary về secondary", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 1280, "y": -2655}}, {"id": "node-muqbul9q-3bim", "data": {"label": "Nên đặt các node trên các server khác nhau (có thể khác cả datacenter hay region)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 1280, "y": -2565}}, {"id": "node-muqbul9q-c4pl", "data": {"label": "Sharding", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 45}, "position": {"x": 640, "y": -2475}}, {"id": "node-muqbul9q-yg38", "data": {"label": "chia dữ liệu ra thành nhiều shard để tăng khả năng lưu trữ dữ liệu (storage scaling) cũng như write scaling\\nMỗi shard là 1 Replication cluster để vẫn đảm bảo HA của hệ thống", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 183}, "position": {"x": 960, "y": -2475}}, {"id": "node-muqbul9q-ai1e", "data": {"label": "Index", "isRoot": false, "collapsed": false, "childCount": 4, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 45}, "position": {"x": 320, "y": -945}}, {"id": "node-muqbul9q-7p8l", "data": {"label": "Index (chỉ mục) nhằm mục đích tăng hiệu suất truy vấn dữ liệu trong CSDL.\\nNếu không có index, CSDL sẽ phải duyệt qua toàn bộ dữ liệu để lấy ra những dữ liệu thỏa mãn điều kiện", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 183}, "position": {"x": 640, "y": -2385}}, {"id": "node-muqbul9q-4zvj", "data": {"label": "Nhược điểm:\\nGiảm hiệu suất của thao tác ghi do phải cập nhật lại index\\nTốn bộ nhớ để lưu trữ index", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 960, "y": -2385}}, {"id": "node-muqbul9q-khnf", "data": {"label": "Các loại index\\nLưu ý: đối với các nested field, thì có thể đánh index tới 100 level, tất nhiên là ko nên sử dụng nhưng mongodb cho phép", "isRoot": false, "collapsed": false, "childCount": 5, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 155}, "position": {"x": 640, "y": -1305}}, {"id": "node-muqbul9q-p1s5", "data": {"label": "single field", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 45}, "position": {"x": 960, "y": -2295}}, {"id": "node-muqbul9q-oj03", "data": {"label": "Có thể tạo trên 1 field hoặc  1 field nằm trong embedded field", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 1280, "y": -2295}}, {"id": "node-muqbul9q-a74i", "data": {"label": "Trường hợp tạo index cho 1 field - mà field đó lại là 1 embedded field (rất ít dùng), thì nó chỉ có tác dụng nếu:\\nquery đủ và đúng thứ tự các fields nằm trong embedded field", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 183}, "position": {"x": 1600, "y": -2295}}, {"id": "node-muqbul9q-cwb6", "data": {"label": "Compound", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 45}, "position": {"x": 960, "y": -1980}}, {"id": "node-muqbul9q-0po0", "data": {"label": "Index được đánh trên 2 (hoặc hơn ko quá 32) fields\\nvd: db.orders.createIndex({ orderId: 1, amount: -1 })", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 1280, "y": -2205}}, {"id": "node-muqbul9q-mtdr", "data": {"label": "Thứ tự các fields khi tạo compound index là rất quan trọng\\nNó hình thành các tiền tố index để hỗ trợ truy vấn theo thứ tự đó", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 1280, "y": -1935}}, {"id": "node-muqbul9q-t9w8", "data": {"label": "db.orders.createIndex{\\norderId: 1,\\namount: -1,\\nstatus: 1\\n}\\nSẽ sinh ra các tiền tố chỉ mục như sau:\\n{ orderId: 1}\\n{ orderId: 1, amount: -1 }\\nThì các query sau sẽ có thể sử dụng index này", "isRoot": false, "collapsed": false, "childCount": 5, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 320}, "position": {"x": 1600, "y": -1935}}, {"id": "node-muqbul9q-iia2", "data": {"label": "{ orderId: <value>  }", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 215, "height": 45}, "position": {"x": 1920, "y": -2115}}, {"id": "node-muqbul9q-qql2", "data": {"label": "{ orderId: <value>, amount: <value> }", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 1920, "y": -2025}}, {"id": "node-muqbul9q-9bin", "data": {"label": "{ orderId: <value>, amount: <value> , status: <value> }", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 1920, "y": -1935}}, {"id": "node-muqbul9q-oxrd", "data": {"label": "{ orderId: <value>, status: <value> }\\nTrường hợp này cũng sẽ sd index, tuy nhiên nó sẽ chỉ tận dụng được index cho orderId, còn status nó sẽ là full scan\\n⟶ nên tối ưu hơn thì sẽ tạo riêng 1 index cho case này", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 210}, "position": {"x": 1920, "y": -1845}}, {"id": "node-muqbul9q-lyd6", "data": {"label": "Lưu ý:\\nthứ tự sắp xếp các fields trong QUERY →  KHÔNG QUAN TRỌNG\\nvd: find({amount: <value>, orderId: <value>, status: <value>}) vẫn ok\\nthứ tự sắp xếp các fields trong SORT → RẤT QUAN TRỌNG\\nvd: sort({amount: -1, orderId: 1}) sẽ không sử dụng được index", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 265}, "position": {"x": 1920, "y": -1755}}, {"id": "node-muqbul9q-yw0a", "data": {"label": "Multikey Index", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 166, "height": 45}, "position": {"x": 960, "y": -1080}}, {"id": "node-muqbul9q-9qdp", "data": {"label": "Đây là việc đánh index cho 1 fields có chứa giá trị là một array\\nBản chất mongodb sẽ tạo index key cho tất cả các giá trị trong mảng đó (và sắp xếp theo giá trị khi đánh index)", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 183}, "position": {"x": 1280, "y": -1620}}, {"id": "node-muqbul9q-vmtj", "data": {"label": "Lưu ý: KHÔNG THỂ TẠO compound index trong đó có 2 fields dạng mảng trở lên\\nTại sao: vì nếu fields đó mà mỗi fields chứa 10 phần tử thì sẽ phải mất 10 × 10 = 100 key index phải được update lại khi có 1 thay đổi → tốn dung lượng bộ nhớ và ảnh hưởng lớn tới hiệu suất", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 265}, "position": {"x": 1600, "y": -1665}}, {"id": "node-muqbul9q-b8f8", "data": {"label": "Trường hợp phần tử trong array là object thì sẽ đánh index theo cú pháp:\\ndb.<collection>.createIndex({ \\"<arrayFields>.<objectKey>: <sorted> })", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 183}, "position": {"x": 1600, "y": -1575}}, {"id": "node-muqbul9q-6fgd", "data": {"label": "Bounds (cực kỳ hay)", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 214, "height": 45}, "position": {"x": 1280, "y": -990}}, {"id": "node-muqbul9q-3qqv", "data": {"label": "(Chỉ nói riêng cho các multikey index) Là cách mà mongoDB giới hạn phạm vi của index trên B-tree để thu hẹp phạm vi scan, cũng chính là tăng tốc độ  truy vấn.", "isRoot": false, "collapsed": false, "childCount": 3, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 155}, "position": {"x": 1600, "y": -990}}, {"id": "node-muqbul9q-17ub", "data": {"label": "Trường hợp 1: Single Index cho một array field KHÔNG có lồng object bên trong", "isRoot": false, "collapsed": false, "childCount": 4, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 1920, "y": -1350}}, {"id": "node-muqbul9q-pr8t", "data": {"label": "DATA:\\ndb.students.insertMany(\\n[\\n{ _id: 1, name: \\"Shawn\\", grades: [ 70, 85 ] },\\n{ _id: 2, item: \\"Elena\\", grades: [ 92, 84 ] }\\n]\\n)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 265}, "position": {"x": 2240, "y": -1485}}, {"id": "node-muqbul9q-3v98", "data": {"label": "INDEX\\ndb.students.createIndex( { grades: 1 } )", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 2240, "y": -1395}}, {"id": "node-muqbul9q-3rc8", "data": {"label": "QUERY 1\\ndb.students.find( { grades : {$gte: 90, $lte: 99 } }  )", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 2240, "y": -1305}}, {"id": "node-muqbul9q-ibg3", "data": {"label": "giới hạn index\\n[ [ 90, Infinity ] ]\\nhoặc\\n[ [ -Infinity, 99 ] ]", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 184, "height": 128}, "position": {"x": 2560, "y": -1305}}, {"id": "node-muqbul9q-tdik", "data": {"label": "QUERY 2: sử dụng $elemMatch\\ndb.students.find( { grades : { $elemMatch: { $gte: 90, $lte: 99 } } } )", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 2240, "y": -1215}}, {"id": "node-muqbul9q-o8va", "data": {"label": "giới hạn index\\n[90, 99]", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 161, "height": 73}, "position": {"x": 2560, "y": -1215}}, {"id": "node-muqbul9q-yqoh", "data": {"label": "Trường hợp 2: Compound Index cho non-array field và array field", "isRoot": false, "collapsed": false, "childCount": 4, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 1920, "y": -990}}, {"id": "node-muqbul9q-fel7", "data": {"label": "DATA\\ndb.survey2.insertMany( [\\n{\\n_id: 1,\\nitem: \\"ABC\\",\\nratings: [ { score: 2, by: \\"mn\\" }, { score: 9, by: \\"anon\\" } ]\\n},\\n{\\n_id: 2,\\nitem: \\"XYZ\\",\\nratings: [ { score: 5, by: \\"anon\\" }, { score: 7, by: \\"wv\\" } ]\\n}\\n] )", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 430}, "position": {"x": 2240, "y": -1125}}, {"id": "node-muqbul9q-4uqx", "data": {"label": "INDEX\\ndb.survey2.createIndex(\\n{\\n\\"item\\": 1,\\n\\"ratings.score\\": 1,\\n\\"ratings.by\\": 1\\n}\\n)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 248, "height": 238}, "position": {"x": 2240, "y": -1035}}, {"id": "node-muqbul9q-cyj7", "data": {"label": "QUERY 1\\ndb.survey2.find(\\n{\\nitem: \\"XYZ\\",\\n\\"ratings.score\\": { $lte: 5 },\\n\\"ratings.by\\": \\"anon\\"\\n}\\n)", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 258, "height": 238}, "position": {"x": 2240, "y": -945}}, {"id": "node-muqbul9q-4ouc", "data": {"label": "giới hạn index\\n{\\n\\"item\\" : [ [ \\"XYZ\\", \\"XYZ\\" ] ],\\n\\"ratings.score\\" : [ [ -Infinity, 5 ]],\\n\\"ratings.by\\" : [ [ MinKey, MaxKey ] ]\\n}\\nhoặc\\n{\\n\\"item\\" : [ [ \\"XYZ\\", \\"XYZ\\" ] ],\\n\\"ratings.score\\" : [ [ MinKey, MaxKey ] ],\\n\\"ratings.by\\" : [ [ \\"anon\\", \\"anon\\" ] ]\\n}", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 375}, "position": {"x": 2560, "y": -945}}, {"id": "node-muqbul9q-l4dj", "data": {"label": "QUERY 2: sử dụng $elemMatch\\ndb.survey2.find( { ratings: { $elemMatch: { score: { $lte: 5 }, by: \\"anon\\" } } } )", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 2240, "y": -855}}, {"id": "node-muqbul9q-zono", "data": {"label": "giới hạn index\\n{\\n\\"item\\" : [ [ \\"XYZ\\", \\"XYZ\\" ] ],\\n\\"ratings.score\\" : [ [ -Infinity, 5 ]],\\n\\"ratings.by\\" : [ [ \\"anon\\", \\"anon\\" ] ]\\n}", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 338, "height": 183}, "position": {"x": 2560, "y": -855}}, {"id": "node-muqbul9q-sfhy", "data": {"label": "Trường hợp 3: Compound index cho nhiều fields nằm trong cùng 1 array", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 1920, "y": -630}}, {"id": "node-muqbul9q-4dhl", "data": {"label": "Để kết hợp được các giới hạn index của các fields nằm trong cùng 1 mảng thì cần thỏa mãn 2 điều kiện sau:\\nCác khóa chỉ mục phải cùng đường dẫn cho tới trước tên field\\nTruy vấn sử dụng $elemMatch trên chính đường dẫn đó\\nvd:  \\"a.b.c.d\\", là đường dẫn trường cho d\\nthì khi query {\\"a.b.c\\": { $elemMatch: { d: <condition> } }", "isRoot": false, "collapsed": false, "childCount": 4, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 348}, "position": {"x": 2240, "y": -630}}, {"id": "node-muqbul9q-eyfa", "data": {"label": "DATA\\ndb.survey3.insertMany( [\\n{\\n_id: 1,\\nitem: \\"ABC\\",\\nratings: [\\n{ scores: [ { q1: 2, q2: 4 }, { q1: 3, q2: 8 } ], loc: \\"A\\" },\\n{ scores: [ { q1: 2, q2: 5 } ], loc: \\"B\\" }\\n]\\n},\\n{\\n_id: 2,\\nitem: \\"XYZ\\",\\nratings: [\\n{ scores: [ { q1: 7 }, { q1: 2, q2: 8 } ], loc: \\"B\\" }\\n]\\n}\\n] )", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 568}, "position": {"x": 2560, "y": -765}}, {"id": "node-muqbul9q-yjl2", "data": {"label": "INDEX\\ndb.survey3.createIndex( { \\"ratings.scores.q1\\": 1, \\"ratings.scores.q2\\": 1 } )", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 2560, "y": -675}}, {"id": "node-muqbul9q-0j5m", "data": {"label": "QUERY 1\\ndb.survey3.find( { ratings: { $elemMatch: { 'scores.q1': 2, 'scores.q2': 8 } } } )", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 2560, "y": -585}}, {"id": "node-muqbul9q-lehf", "data": {"label": "giới hạn index\\n{\\n'ratings.scores.q1': [\\n'[2, 2]'\\n],\\n'ratings.scores.q2': [\\n'[minKey, maxKey]'\\n]\\n}", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 211, "height": 265}, "position": {"x": 2880, "y": -585}}, {"id": "node-muqbul9q-891n", "data": {"label": "QUERY 2\\ndb.survey3.find( { 'ratings.scores': { $elemMatch: { 'q1': 2, 'q2': 8 } } } )", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 2560, "y": -495}}, {"id": "node-muqbul9q-ziho", "data": {"label": "giới hạn index\\n{\\n'ratings.scores.q1': [\\n'[2, 2]'\\n],\\n'ratings.scores.q2': [\\n'[8, 8]'\\n]\\n}", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 211, "height": 265}, "position": {"x": 2880, "y": -495}}, {"id": "node-muqbul9q-z6zz", "data": {"label": "Wildcard (chỉ mục ký tự đại diện)", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 332, "height": 45}, "position": {"x": 960, "y": -405}}, {"id": "node-muqbul9q-qtms", "data": {"label": "Nó sinh ra không phải để thay thế cho các index thông thường mà là để giải quyết bài toán Polymorphic schema (lược đồ động) - khi mà không thể đoán trước các trường", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 155}, "position": {"x": 1280, "y": -405}}, {"id": "node-muqbul9q-u2jz", "data": {"label": "USE CASE:\\nChúng ta không thể định nghĩa được tất cả các thuộc tính của sản phẩm, nó có thể được thêm vào từ người dùng → không thể định nghĩa được trước các fields tương ứng", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 210}, "position": {"x": 1600, "y": -405}}, {"id": "node-muqbul9q-foru", "data": {"label": "Tạo wildcard index cho các thuộc tính đó\\nvà cách làm nên là gộp chúng vào 1 sub-document rồi wildcard index cho sub-document đó\\n// CHỈ đánh index cho các trường vô định bên trong cụm attributes\\ndb.products.createIndex( { \\"attributes.$**\\": 1 } )", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 265}, "position": {"x": 1920, "y": -405}}, {"id": "node-muqbul9q-htvn", "data": {"label": "Hash", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 45}, "position": {"x": 960, "y": -315}}, {"id": "node-muqbul9q-lplf", "data": {"label": "Xóa Index", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 45}, "position": {"x": 640, "y": -225}}, {"id": "node-muqbul9q-xppp", "data": {"label": "Cách xóa thì lên Doc đọc nhé 😀\\nNhưng có khuyến nghị sau nên tập trung", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 960, "y": -225}}, {"id": "node-muqbul9q-lh8p", "data": {"label": "Trước khi xóa 1 index bất kỳ, nên ẨN INDEX đó đi trước để đánh giá tác động của nó.\\nẨn index chỉ làm cho query planer không sử dụng được, còn các thao tác ghi thì vẫn cập nhật index đó như bình thường.\\nCó thể hiện lại index", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 238}, "position": {"x": 1280, "y": -225}}, {"id": "node-muqbul9q-kik6", "data": {"label": "Các properties cho index", "isRoot": false, "collapsed": false, "childCount": 5, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 257, "height": 45}, "position": {"x": 640, "y": 180}}, {"id": "node-muqbul9q-g4gb", "data": {"label": "hide/unhide (ẩn/hiện) index", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 286, "height": 45}, "position": {"x": 960, "y": -135}}, {"id": "node-muqbul9q-zh1p", "data": {"label": "Chỉ làm cho query planer không sử dụng được, còn các thao tác ghi thì vẫn cập nhật index đó như bình thường", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 1280, "y": -135}}, {"id": "node-muqbul9q-5mp0", "data": {"label": "TTL (time to live)", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 185, "height": 45}, "position": {"x": 960, "y": 0}}, {"id": "node-muqbul9q-goqs", "data": {"label": "Thiết lập thời gian tồn tại của document được thiết lập index có TTL", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 1280, "y": 0}}, {"id": "node-muqbul9q-f5pc", "data": {"label": "Thích hợp cho các dữ liệu cần xóa sau 1 khoảng thời gian\\nvd: session, log...", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 1600, "y": -45}}, {"id": "node-muqbul9q-ceum", "data": {"label": "Lưu ý là mongodb sẽ thực hiện xóa các document hết hạn trong trình chạy nền theo chu kỳ (vd: 60s 1 lần) nên đối với các nghiệp vụ cần xóa chính xác thì ko nên dùng TTL index", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 155}, "position": {"x": 1920, "y": -45}}, {"id": "node-muqbul9q-94ua", "data": {"label": "Cần lưu ý về thời điểm tạo index có TTL, để tránh ảnh hưởng hiệu suất của DB khi có nhiều document thỏa mãn điều kiện TTL nên sẽ bị xóa cùng 1 lúc", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 155}, "position": {"x": 1600, "y": 45}}, {"id": "node-muqbul9q-ykon", "data": {"label": "Có thể nên xóa các document đó trước khi đánh index", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 1920, "y": 45}}, {"id": "node-muqbul9q-0if4", "data": {"label": "Partial (index 1 phần)", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 223, "height": 45}, "position": {"x": 960, "y": 135}}, {"id": "node-muqbul9q-wyau", "data": {"label": "Thiết lập index nhưng kèm điều kiện (có thể hiểu là không đánh index toàn bộ documents trong collection)", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 1280, "y": 135}}, {"id": "node-muqbul9q-zo48", "data": {"label": "vd: chỉ đánh index trên field “name” cho document có tồn tại field “password”\\ndb.users.createIndex(\\n{ name: 1 },\\n{ partialFilterExpression: { password: { $exists: true } } }\\n)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 238}, "position": {"x": 1600, "y": 135}}, {"id": "node-muqbul9q-dk98", "data": {"label": "index cho string field để không phân biệt chữ hoa/thường", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 960, "y": 315}}, {"id": "node-muqbul9q-556g", "data": {"label": "db.collection.createIndex(\\n{\\n<field>: <sortOrder>\\n},\\n{\\ncollation:\\n{\\nlocale : <locale>,\\nstrength : < 1 | 2 >\\n}\\n}\\n)", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 266, "height": 348}, "position": {"x": 1280, "y": 315}}, {"id": "node-muqbul9q-xefq", "data": {"label": "Lưu ý: khi tạo index có strength bằng bao nhiêu\\nthì query cũng phải query theo strength bằng bấy nhiêu thì index mới được sử dụng", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 155}, "position": {"x": 1600, "y": 270}}, {"id": "node-muqbul9q-40uu", "data": {"label": "db.createCollection(\\"fruit\\")\\ndb.fruit.createIndex(\\n{ type: 1 },\\n{ collation: { locale: 'en', strength: 2 } }\\n)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 183}, "position": {"x": 1920, "y": 225}}, {"id": "node-muqbul9q-z7f9", "data": {"label": "db.fruit.insertMany( [\\n{ type: \\"apple\\" },\\n{ type: \\"Apple\\" },\\n{ type: \\"APPLE\\" }\\n] )\\ndb.fruit.find( { type: \\"apple\\" } ) // does not use index, finds one result\\ndb.fruit.find( { type: \\"apple\\" } ).collation( { locale: 'en', strength: 2 } )\\n// uses the index, finds three results\\ndb.fruit.find( { type: \\"apple\\" } ).collation( { locale: 'en', strength: 1 } )\\n// does not use the index, finds three results", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 458}, "position": {"x": 1920, "y": 315}}, {"id": "node-muqbul9q-3jqr", "data": {"label": "Hoặc có thể thiết lập sự đối chiếu ngay từ lúc tạo collection\\nthì các query sẽ kế thừa sự đối chiếu đó (ngoại trừ trường hợp thiết lập đối chiếu khác)", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 155}, "position": {"x": 1600, "y": 405}}, {"id": "node-muqbul9q-82j7", "data": {"label": "db.createCollection(\\"names\\", { collation: { locale: 'en_US', strength: 2 } } )\\ndb.names.createIndex( { first_name: 1 } ) // inherits the default collation", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 155}, "position": {"x": 1920, "y": 405}}, {"id": "node-muqbul9q-p4mx", "data": {"label": "unique", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 45}, "position": {"x": 960, "y": 495}}, {"id": "node-muqbul9q-gml1", "data": {"label": "Thiết lập index và đánh dấu fields hoặc compound fileds chỉ có giá trị duy nhất trong 1 collection", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 1280, "y": 495}}, {"id": "node-muqbul9q-8zqa", "data": {"label": "BSON", "isRoot": false, "collapsed": false, "childCount": 3, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 45}, "position": {"x": 320, "y": 810}}, {"id": "node-muqbul9r-i4zi", "data": {"label": "JSON là gì?", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 45}, "position": {"x": 640, "y": 630}}, {"id": "node-muqbul9r-9ivz", "data": {"label": "JSON là một định dạng dữ liệu dựa trên văn bản, tuân theo cú pháp Object trong JS. Nó biểu diễn dữ liệu có cấu trúc dưới dạng chuỗi, rất hữu ích để truyền tải dữ liệu qua mạng.", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 183}, "position": {"x": 960, "y": 585}}, {"id": "node-muqbul9r-zg9l", "data": {"label": "JSON chỉ có thể chứa dữ liệu có kiểu: string, number, boolean, null, object và array (không chứa được undefined, NaN, Date, Map, Set)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 960, "y": 675}}, {"id": "node-muqbul9r-c7nl", "data": {"label": "BSON là gì?", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 45}, "position": {"x": 640, "y": 810}}, {"id": "node-muqbul9r-5yop", "data": {"label": "BSON = Binary JSON: là định dạng mã hóa nhị phân của JSON", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 960, "y": 765}}, {"id": "node-muqbul9r-r5td", "data": {"label": "BSON bổ sung thêm các kiểu dữ liệu mà JSON không có như: Date, Decimal128, ObjectId...", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 960, "y": 855}}, {"id": "node-muqbul9r-5g53", "data": {"label": "Tại sao lại dùng BSON?", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 242, "height": 45}, "position": {"x": 640, "y": 990}}, {"id": "node-muqbul9r-vrkv", "data": {"label": "BSON có nhiều kiểu dữ liệu", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 280, "height": 45}, "position": {"x": 960, "y": 945}}, {"id": "node-muqbul9r-sgo9", "data": {"label": "BSON có chứa metadata về kiểu và độ dài của dữ liệu, giúp việc scan (quét để tìm kiếm) dữ liệu nhanh hơn so với JSON\\nTuy nhiên nó sẽ đọc chậm hơn do cần parse data", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 183}, "position": {"x": 960, "y": 1035}}, {"id": "node-muqbul9r-kng5", "data": {"label": "ACID", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 45}, "position": {"x": 320, "y": 1440}}, {"id": "node-muqbul9r-u9zr", "data": {"label": "Giao dịch CSDL là gì?", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 223, "height": 45}, "position": {"x": 640, "y": 1170}}, {"id": "node-muqbul9r-o4dg", "data": {"label": "Là một nhóm các thao tác đọc, ghi đã được hoàn thành thành công theo định nghĩa của hệ quản trị CSDL", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 960, "y": 1170}}, {"id": "node-muqbul9r-d5fq", "data": {"label": "Giao dịch đơn lẻ (single transaction)", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 359, "height": 45}, "position": {"x": 1280, "y": 1125}}, {"id": "node-muqbul9r-medm", "data": {"label": "Là tập hợp của một hoặc nhiều thao tác db dẫn đến một hành động duy nhất được hoàn thành thành công.\\nSau khi hoàn tất thì giao dịch được chấp nhận và có thể tìm thấy trong nhật ký giao dịch\\nVD: giao dịch rút tiền từ cây ATM (qua nhiều thao tác thì hành động duy nhất là trừ tiền trong tk ngân hàng)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 320}, "position": {"x": 1600, "y": 1125}}, {"id": "node-muqbul9r-dt0x", "data": {"label": "Giao dịch thành phần (phân tán) - multi-transactions", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 1280, "y": 1215}}, {"id": "node-muqbul9r-luc0", "data": {"label": "Gồm nhiều giao dịch phụ thuộc lẫn nhau trải rộng trên các thành phần trong CSDL (documents,  collections), CSDL và hệ thống khác nhau\\nVD: giao dịch chuyển tiền từ người A sang B\\ncần đảm bảo trừ tiền người A và cộng tiền cho người B", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 265}, "position": {"x": 1600, "y": 1215}}, {"id": "node-muqbul9r-1ybu", "data": {"label": "Giao dịch ACID", "isRoot": false, "collapsed": false, "childCount": 4, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 169, "height": 45}, "position": {"x": 640, "y": 1530}}, {"id": "node-muqbul9r-sgkw", "data": {"label": "Atomicity  (tính nguyên tử)", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 278, "height": 45}, "position": {"x": 960, "y": 1350}}, {"id": "node-muqbul9r-w4uc", "data": {"label": "Đảm bảo tất cả các lệnh cấu thành 1 giao dịch được xử lý như một đơn vị duy nhất và cùng thành công hoặc cùng thất bại", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 1280, "y": 1350}}, {"id": "node-muqbul9r-6u5w", "data": {"label": "Đối với giao dịch trên 1 document thì nó đã là Atomicity (mặc định, không cần setup gì thêm)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 1600, "y": 1305}}, {"id": "node-muqbul9r-77tl", "data": {"label": "Đối với giao dịch trên nhiều documents, MongoDB hỗ trợ giao dịch trên replica sets hay sharded cluster", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 1600, "y": 1395}}, {"id": "node-muqbul9r-b3kl", "data": {"label": "Consistency (tính nhất quán)", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 292, "height": 45}, "position": {"x": 960, "y": 1485}}, {"id": "node-muqbul9r-fj0n", "data": {"label": "Đảm bảo các thay đổi thực hiện trên một giao dịch được cập nhật trên toàn hệ thống CSDL (vd: các nút trên 1 replica set và mức độ tới đâu thì dựa vào WriteConcern  chúng ta  thiết lập) và phù hợp với các ràng buộc của hệ quản trị CSDL (vd: unique index, data type of fileds...)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 265}, "position": {"x": 1280, "y": 1485}}, {"id": "node-muqbul9r-2kzm", "data": {"label": "Isolation (tính cô lập)", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 225, "height": 45}, "position": {"x": 960, "y": 1620}}, {"id": "node-muqbul9r-7ve4", "data": {"label": "Mỗi giao dịch sẽ được tách biệt hoàn toàn khỏi các giao dịch khác để ngăn ngừa xung đột dữ liệu", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 1280, "y": 1620}}, {"id": "node-muqbul9r-7yqk", "data": {"label": "2 giao dịch của sửa đổi một document thì mongoDB sẽ có cơ chế lock lại các giao dịch phía sau để chờ giao dịch đầu tiên được hoàn tất", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 155}, "position": {"x": 1600, "y": 1575}}, {"id": "node-muqbul9r-r5vu", "data": {"label": "MongoDB sử dụng cơ chế “snapshot” mỗi khi bắt đầu một giao dịch, giao dịch sẽ đọc dữ liệu đã được snapshot đó và nếu có bất kỳ xung đột nào thì giao dịch sẽ bị hủy bỏ", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 183}, "position": {"x": 1600, "y": 1665}}, {"id": "node-muqbul9r-4qjr", "data": {"label": "Durability (tính bền vững)", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 267, "height": 45}, "position": {"x": 960, "y": 1755}}, {"id": "node-muqbul9r-hy1b", "data": {"label": "Khi giao dịch được hoàn tất, các thay đổi sẽ được ghi vào CSDL thì chúng sẽ được lưu giữ và giả sử có bất kỳ sự cố nào về hệ thống (sập hệ thống hay mất điện) thì dữ liệu vẫn tồn tại", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 183}, "position": {"x": 1280, "y": 1755}}, {"id": "node-muqbul9r-iawn", "data": {"label": "MongoDB tạo một OpLog để lưu trữ vị trí ổ đĩa và số byte đã thay đổi của mỗi thao tác ghi.\\nNên nếu có sự cố (vd như mất điện) trong quá trình ghi giao dịch thì sau khi hệ thống hoạt động trở lại thì OpLog được sử dụng để phát lại các thao tác ghi bị treo đó để ghi lại vào ổ đĩa", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 265}, "position": {"x": 1600, "y": 1755}}, {"id": "node-muqbul9r-eq1i", "data": {"label": "Aggregation", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#8b5cf6"}, "type": "mindmap", "hidden": false, "measured": {"width": 146, "height": 45}, "position": {"x": 320, "y": 2115}}, {"id": "node-muqbul9r-j35c", "data": {"label": "Dùng để xử lý nhiều document thông qua các stage để cho ra kết quả đã được tính toán.\\nOutput của stage này là Input của stage kế tiếp", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#8b5cf6"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 155}, "position": {"x": 640, "y": 2070}}, {"id": "node-muqbul9r-c7hf", "data": {"label": "Một số stage phổ biến", "isRoot": false, "collapsed": false, "childCount": 6, "branchColor": "#8b5cf6"}, "type": "mindmap", "hidden": false, "measured": {"width": 236, "height": 45}, "position": {"x": 960, "y": 2070}}, {"id": "node-muqbul9r-rnpu", "data": {"label": "$match: lọc dữ liệu theo điều kiện (nên đặt trên cùng hoặc sớm nhất có thể trong aggregation)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#8b5cf6"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 1280, "y": 1845}}, {"id": "node-muqbul9r-w8s9", "data": {"label": "$projection: lọc fileds cần lấy ra (giảm thiểu input size cho stage sau)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#8b5cf6"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 1280, "y": 1935}}, {"id": "node-muqbul9r-wfvu", "data": {"label": "$group: nhóm dữ liệu theo field nhất định", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#8b5cf6"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 1280, "y": 2025}}, {"id": "node-muqbul9r-nbne", "data": {"label": "$unwind: bóc tách các array element thành từng document riêng biệt", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#8b5cf6"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 1280, "y": 2115}}, {"id": "node-muqbul9r-wgg0", "data": {"label": "$lookup: left join collection, nó sẽ trả về document có chứa thêm field là một mảng các documents phù hợp từ collection đích", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#8b5cf6"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 1280, "y": 2205}}, {"id": "node-muqbul9r-s9rf", "data": {"label": "Lưu ý quan trọng: điều kiện trong $lookup không có index nên hiệu suất của $lookup sẽ thấp", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#8b5cf6"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 1600, "y": 2205}}, {"id": "node-muqbul9r-1hgw", "data": {"label": "$sort, $limit, $skip: sắp xếp, giới hạn số lượng, bỏ qua số lượng document", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#8b5cf6"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 1280, "y": 2295}}, {"id": "node-muqbul9r-dn8l", "data": {"label": "Trong 1 aggregation pipeline có max = 1000 stage\\nStage size max = 100MB", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#8b5cf6"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 640, "y": 2385}}, {"id": "node-muqbul9r-kc77", "data": {"label": "OpLog là gì?", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#f97316"}, "type": "mindmap", "hidden": false, "measured": {"width": 146, "height": 45}, "position": {"x": 320, "y": 2475}}, {"id": "node-muqbul9r-5yfb", "data": {"label": "OpLog dùng để ghi lại những thao tác (insert/update/delete) trên primary node để cho secondary node thực hiện theo nhằm mục đích đồng bộ dữ liệu giữa primary và secondary node", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f97316"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 183}, "position": {"x": 640, "y": 2475}}, {"id": "node-muqbul9r-sgak", "data": {"label": "Cursor", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#14b8a6"}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 45}, "position": {"x": 320, "y": 2610}}, {"id": "node-muqbul9r-h6f7", "data": {"label": "Trong find() hoặc aggregate() thì kết quả trả về sẽ là một con trỏ trỏ tới 1 tập dữ liệu (thường là 1 phần - batch)", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#14b8a6"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 640, "y": 2610}}, {"id": "node-muqbul9r-gask", "data": {"label": "Để trả ra kết quả cho ứng dụng sử dụng được", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#14b8a6"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 960, "y": 2610}}, {"id": "node-muqbul9r-4f8h", "data": {"label": ".toArray()", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#14b8a6"}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 45}, "position": {"x": 1280, "y": 2565}}, {"id": "node-muqbul9r-0rr8", "data": {"label": "Nên sử dụng cùng pagination để tránh overload dữ liệu", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#14b8a6"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 1600, "y": 2565}}, {"id": "node-muqbul9r-j6qk", "data": {"label": "Lặp qua cursor\\nVD:\\nlet myCursor = db.users.find( { type: \\"user\\" } )\\nwhile ( myCursor.hasNext() ) {\\nprintjson( myCursor.next() )\\n}", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#14b8a6"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 210}, "position": {"x": 1280, "y": 2655}}, {"id": "node-muqbul9r-fmj3", "data": {"label": "Capped collection", "isRoot": false, "collapsed": false, "childCount": 3, "branchColor": "#3b82f6"}, "ty