type": "mindmap", "hidden": false, "source": "node-muqbqt3q-6dku", "target": "node-muqbqt3q-gwqk"}, {"id": "edge-node-muqbqt3q-h9yc-node-muqbqt3q-2t5x", "data": {"color": "#06b6d4"}, "type": "mindmap", "hidden": false, "source": "node-muqbqt3q-h9yc", "target": "node-muqbqt3q-2t5x"}, {"id": "edge-node-muqbqt3q-2t5x-node-muqbqt3q-8fg1", "data": {"color": "#06b6d4"}, "type": "mindmap", "hidden": false, "source": "node-muqbqt3q-2t5x", "target": "node-muqbqt3q-8fg1"}, {"id": "edge-node-muqbqt3q-8fg1-node-muqbqt3q-ap4f", "data": {"color": "#06b6d4"}, "type": "mindmap", "hidden": false, "source": "node-muqbqt3q-8fg1", "target": "node-muqbqt3q-ap4f"}, {"id": "edge-node-muqbqt3q-8fg1-node-muqbqt3q-b88t", "data": {"color": "#06b6d4"}, "type": "mindmap", "hidden": false, "source": "node-muqbqt3q-8fg1", "target": "node-muqbqt3q-b88t"}], "nodes": [{"id": "root", "data": {"label": "Javascript", "isRoot": true, "collapsed": false, "childCount": 5}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 44}, "position": {"x": 0, "y": 0}}, {"id": "node-muqbqt3p-5esk", "data": {"label": "Callback, Promise, Async/Await", "isRoot": false, "collapsed": false, "childCount": 4, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 315, "height": 45}, "position": {"x": 320, "y": -1755}}, {"id": "node-muqbqt3p-aeen", "data": {"label": "Callback: là 1 function được truyền vào như 1 tham số của 1 function khác và nó được thực thi khi sự kiện xảy ra", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 640, "y": -2025}}, {"id": "node-muqbqt3p-63lq", "data": {"label": "có thể làm được điều này là do JS có first-class function nó cho phép gán function vào biến hoặc truyền function như là 1 tham số đầu vào cho function khác (được gọi là higher-order function)", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 183}, "position": {"x": 960, "y": -2025}}, {"id": "node-muqbqt3p-k97u", "data": {"label": "fist-class function: là một đặc tính trong JS nó cho phép", "isRoot": false, "collapsed": false, "childCount": 3, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 1280, "y": -2115}}, {"id": "node-muqbqt3p-zgrd", "data": {"label": "gán 1 function vào 1 biến", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 257, "height": 45}, "position": {"x": 1600, "y": -2205}}, {"id": "node-muqbqt3p-71fl", "data": {"label": "truyền 1 function vào 1 function khác", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 1600, "y": -2115}}, {"id": "node-muqbqt3p-8xtl", "data": {"label": "trả về 1 function trong 1 function khác (đây là nền tảng của closure)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 1600, "y": -2025}}, {"id": "node-muqbqt3p-uj0d", "data": {"label": "higher-order function: là 1 function có ít nhất 1 trong 2 đặc điểm sau", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 1280, "y": -1890}}, {"id": "node-muqbqt3p-t6vo", "data": {"label": "Trả về 1 function như kết quả đầu ra", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 358, "height": 45}, "position": {"x": 1600, "y": -1935}}, {"id": "node-muqbqt3p-arvs", "data": {"label": "Nhận 1 (hoặc nhiều) function làm tham số đầu vào", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 1600, "y": -1845}}, {"id": "node-muqbqt3p-fxm3", "data": {"label": "Promise: là 1 JS object đặc biệt, nó đại diện cho kết quả (thành công hoặc thất bại) của một thao tác bất đồng bộ", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 640, "y": -1665}}, {"id": "node-muqbqt3p-82ij", "data": {"label": "Promise có 3 trạng thái", "isRoot": false, "collapsed": false, "childCount": 3, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 243, "height": 45}, "position": {"x": 960, "y": -1665}}, {"id": "node-muqbqt3p-2vlf", "data": {"label": "Pending: là trạng thái chờ thao tác bất đồng bộ xử lý", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 1280, "y": -1755}}, {"id": "node-muqbqt3p-shj6", "data": {"label": "Fulfilled: là trạng thái thành công, thao tác bất đồng bộ trả về kết quả", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 1280, "y": -1665}}, {"id": "node-muqbqt3p-k6iv", "data": {"label": "Rejected: là trạng thái thất bại, thao tác bất đồng bộ trả về lỗi", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 1280, "y": -1575}}, {"id": "node-muqbqt3p-5ipi", "data": {"label": "Async/Await: là các keywork sử dụng cùng với Promise để viết code bất đồng bộ trông như code đồng bộ", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 640, "y": -1440}}, {"id": "node-muqbqt3p-li2o", "data": {"label": "async: sử dụng để định nghĩa 1 function có kết quả trả về là 1 Promise", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 960, "y": -1485}}, {"id": "node-muqbqt3p-7k7v", "data": {"label": "await: sử dụng bên trong async function, nó dùng để tạm dừng thực thi cho đến khi Promise được hoàn thành", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 960, "y": -1395}}, {"id": "node-muqbqt3p-0y34", "data": {"label": "Một số lưu ý", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 146, "height": 45}, "position": {"x": 640, "y": -1305}}, {"id": "node-muqbqt3p-dwpv", "data": {"label": "Khi sử dụng Promise hoặc async/await, luôn luôn phải xử lý bắt lỗi (catch trong Promise hay try/catch trong async/await) nếu không sẽ có thể gây ra crash chương trình với lỗi unhandledRejection", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 210}, "position": {"x": 960, "y": -1305}}, {"id": "node-muqbqt3p-3m7c", "data": {"label": "Hoisting", "isRoot": false, "collapsed": false, "childCount": 6, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 45}, "position": {"x": 320, "y": -810}}, {"id": "node-muqbqt3p-tw9a", "data": {"label": "Chúng ta hay nhớ hoisting theo cách hiểu là đưa các khai báo biến và function lên cùng trước khi thực thi mã nguồn", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 640, "y": -1215}}, {"id": "node-muqbqt3p-uvzt", "data": {"label": "Thực tế, chúng ta sẽ đi sâu vào JS engine (V8) xử lý mã nguồn qua 2 giai đoạn", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 640, "y": -1080}}, {"id": "node-muqbqt3p-uop8", "data": {"label": "Creation phase: sẽ quét qua toàn bộ mã nguồn tìm các biến và hàm rồi cấp phát bộ nhớ cho chúng ngay lập tức", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 960, "y": -1125}}, {"id": "node-muqbqt3p-se15", "data": {"label": "Excution phase: Code chạy từng dòng từ trên xuống dưới, khi gặp khai báo biến thì lúc này mới gán giá trị cho biến. Còn riêng function thì toàn bộ nội dung đã được đưa vào bộ nhớ ở Creation phase", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 183}, "position": {"x": 960, "y": -1035}}, {"id": "node-muqbqt3p-z94o", "data": {"label": "Hoisting với function", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 223, "height": 45}, "position": {"x": 640, "y": -900}}, {"id": "node-muqbqt3p-48px", "data": {"label": "function được hoisted toàn bộ nội dung nên có thể gọi trước khi khai báo mà không gây ra lỗi", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 960, "y": -945}}, {"id": "node-muqbqt3p-6ozi", "data": {"label": "sayHello(); // Output: \\"Chào người anh em!\\"\\nfunction sayHello() {\\nconsole.log(\\"Chào người anh em!\\");\\n}", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 155}, "position": {"x": 1280, "y": -945}}, {"id": "node-muqbqt3p-s5zw", "data": {"label": "Lưu ý: đối với Function expression và Arrow function thì được hoisted dựa vào từ khóa khai báo biến (var, let, const), chứ không theo kiểu Function declaration", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 155}, "position": {"x": 960, "y": -855}}, {"id": "node-muqbqt3p-z265", "data": {"label": "sum(1, 2);\\nvar sum = (a, b) => a + b;\\n//Nếu dùng var ⇒ TypeError: sum is not a function (vì var thì sẽ được hoisted và gán giá trị là undefined)\\n// Nếu dùng let/const ⇒ ReferenceError  (vì let/const được hoisted nhưng không được gán giá trị nên chưa được tham chiếu tới bất kỳ giá trị nào)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 293}, "position": {"x": 1280, "y": -855}}, {"id": "node-muqbqt3p-2ud4", "data": {"label": "Hoisting với var", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 175, "height": 45}, "position": {"x": 640, "y": -765}}, {"id": "node-muqbqt3p-nfno", "data": {"label": "khi khai báo biến với var, biến sẽ được hoisted và gán giá trị là undefined", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 960, "y": -765}}, {"id": "node-muqbqt3p-dru2", "data": {"label": "console.log(tech); // Output: undefined\\nvar tech = \\"Nodejs\\";\\nconsole.log(tech); // Output: \\"Nodejs\\"", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 155}, "position": {"x": 1280, "y": -765}}, {"id": "node-muqbqt3p-tblw", "data": {"label": "Hoisting với let/const", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 227, "height": 45}, "position": {"x": 640, "y": -675}}, {"id": "node-muqbqt3p-43fx", "data": {"label": "khi khai báo biến với let/const biến sẽ được hoisted và chưa gán bất kỳ giá trị nào", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 960, "y": -675}}, {"id": "node-muqbqt3p-8sf4", "data": {"label": "Lời khuyên", "isRoot": false, "collapsed": false, "childCount": 3, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 45}, "position": {"x": 640, "y": -495}}, {"id": "node-muqbqt3p-6qzl", "data": {"label": "Tránh dùng var, Nên dùng let/const", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 354, "height": 45}, "position": {"x": 960, "y": -585}}, {"id": "node-muqbqt3p-sktx", "data": {"label": "Luôn khai báo biến ở đầu scope", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 321, "height": 45}, "position": {"x": 960, "y": -495}}, {"id": "node-muqbqt3p-gyig", "data": {"label": "Khai báo hàm trước khi gọi", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 278, "height": 45}, "position": {"x": 960, "y": -405}}, {"id": "node-muqbqt3p-jw09", "data": {"label": "Closure", "isRoot": false, "collapsed": false, "childCount": 6, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 45}, "position": {"x": 320, "y": 135}}, {"id": "node-muqbqt3p-3ayp", "data": {"label": "Lexical scoping", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 169, "height": 45}, "position": {"x": 640, "y": -270}}, {"id": "node-muqbqt3p-o47s", "data": {"label": "có nghĩa là phạm vi của một biến được xác định là vị trí biến đó được khai báo, chứ không phải là vị trí mà hàm chứa biến đó được gọi", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 960, "y": -315}}, {"id": "node-muqbqt3p-yp29", "data": {"label": "Cách JS Engine nhìn code của bạn: khi trình biên dịch quét qua code thì nó sẽ ghi nhớ theo kiểu: “Hàm A nằm trong global scope, biến X nằm trong hàm A, hàm B nằm trong hàm A”", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 183}, "position": {"x": 960, "y": -225}}, {"id": "node-muqbqt3p-s82w", "data": {"label": "Scope chain", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 141, "height": 45}, "position": {"x": 640, "y": -135}}, {"id": "node-muqbqt3p-84y8", "data": {"label": "Khi tìm 1 biến, JS sẽ tìm từ Local scope (phạm vi trong hàm đó) ⟶ sau đó sẽ tới các outer scope (phạm vi các hàm cha theo thứ tự lần lượt từ trong ra ngoài) ⟶ Global scope ⟶ nếu ko tìm thấy thì trả ra lỗi ReferenceError", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 210}, "position": {"x": 960, "y": -135}}, {"id": "node-muqbqt3p-w0xi", "data": {"label": "Closure: thể hiện 1 hàm con có khả năng ghi nhớ các biến, tham số trong phạm vi của hàm cha, ngay cả khi hàm cha đã kết thúc thực thi", "isRoot": false, "collapsed": false, "childCount": 3, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 640, "y": 45}}, {"id": "node-muqbqt3p-x7le", "data": {"label": "Hàm được khai báo lồng trong 1 hàm khác", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 960, "y": -45}}, {"id": "node-muqbqt3p-tnzt", "data": {"label": "Hàm con (bên trong) sử dụng các biến của hàm cha (bên ngoài)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 960, "y": 45}}, {"id": "node-muqbqt3p-cgl5", "data": {"label": "Hàm con ghi nhớ (đóng gói lại) môi trường của hàm cha, giữ cho các biến không bị giải phóng khỏi bộ nhớ, cho phép hàm con sử dụng sau đó", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 155}, "position": {"x": 960, "y": 135}}, {"id": "node-muqbqt3p-1t5z", "data": {"label": "Ví dụ: hàm counter, logger, middleware", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 640, "y": 225}}, {"id": "node-muqbqt3p-619v", "data": {"label": "Ưu điểm", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 45}, "position": {"x": 640, "y": 360}}, {"id": "node-muqbqt3p-oobf", "data": {"label": "Bảo mật dữ liệu (biến private)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 302, "height": 45}, "position": {"x": 960, "y": 315}}, {"id": "node-muqbqt3p-79p7", "data": {"label": "Code gọn gàng hơn, module hóa", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 332, "height": 45}, "position": {"x": 960, "y": 405}}, {"id": "node-muqbqt3p-jugd", "data": {"label": "Nhược điểm", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 144, "height": 45}, "position": {"x": 640, "y": 540}}, {"id": "node-muqbqt3p-dy58", "data": {"label": "Dễ gây ra tràn bộ nhớ (memory leak)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 960, "y": 495}}, {"id": "node-muqbqt3p-7b65", "data": {"label": "Khó debug code nếu lạm dụng việc sử dụng hàm lồng nhau", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 960, "y": 585}}, {"id": "node-muqbqt3p-9nsn", "data": {"label": "Prototype", "isRoot": false, "collapsed": false, "childCount": 4, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 45}, "position": {"x": 320, "y": 900}}, {"id": "node-muqbqt3q-tkef", "data": {"label": "Là một cơ chế mà 1 object kế thừa các phương thức và thuộc tính của đối tượng cha", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 640, "y": 675}}, {"id": "node-muqbqt3q-8rw5", "data": {"label": "bản chất đằng sau “class” trong ES6 chính là “prototype”", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 960, "y": 675}}, {"id": "node-muqbqt3q-jbdc", "data": {"label": "phân biệt prototype vs __proto__", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 328, "height": 45}, "position": {"x": 640, "y": 810}}, {"id": "node-muqbqt3q-ymko", "data": {"label": "prototye: là keyword dùng để khai báo các phương thức và thuộc tính để các instance (thực thể) được tạo ra từ hàm này (function constructor) được kế thừa và sử dụng", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 183}, "position": {"x": 960, "y": 765}}, {"id": "node-muqbqt3q-3woy", "data": {"label": "__proto__: là keyword dùng để link tới các phương thức và thuộc tính của hàm cha (function constructor) được tạo ra thông qua prototye keyword", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 155}, "position": {"x": 960, "y": 855}}, {"id": "node-muqbqt3q-2khi", "data": {"label": "Ưu điểm", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 45}, "position": {"x": 640, "y": 990}}, {"id": "node-muqbqt3q-t5ey", "data": {"label": "Giúp xây dựng theo hướng đối tượng", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 960, "y": 945}}, {"id": "node-muqbqt3q-1y4y", "data": {"label": "Tối ưu bộ nhớ - vì các phương thức/ thuộc tính tạo bởi prototype thì sẽ chỉ khai báo 1 lần, và không khai báo lại khi khởi tạo 1 đối tượng mới", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 155}, "position": {"x": 960, "y": 1035}}, {"id": "node-muqbqt3q-5qlm", "data": {"lab