0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 640, "y": -405}}, {"id": "node-muqbu6ki-phlj", "data": {"label": "Union type: là kiểu gộp nhiều type trong 1 type\\nvd: number | string hay boolean | number | string", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 640, "y": -315}}, {"id": "node-muqbu6ki-3ac0", "data": {"label": "Never type: là kiểu trả về của fn với mục đích khẳng định fn đó không trả về dữ liệu gì cả (vd: throw Exception)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 640, "y": -225}}, {"id": "node-muqbu6ki-ul5w", "data": {"label": "Void type: thường dùng cho fn mà không có kết quả trả về (ko return về giá trị gì)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 640, "y": -135}}, {"id": "node-muqbu6ki-778c", "data": {"label": "aliases type: là định nghĩa gộp của hai hoặc nhiều premitive type\\nvd: type stringAndNumber = string | number;", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 640, "y": -45}}, {"id": "node-muqbu6ki-o61h", "data": {"label": "Function", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 45}, "position": {"x": 320, "y": 45}}, {"id": "node-muqbu6ki-3z08", "data": {"label": "Function overloading", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 225, "height": 45}, "posit