or": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 174, "height": 45}, "position": {"x": 640, "y": 405}}, {"id": "node-muqbu6ki-1w1k", "data": {"label": "Abstract class", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 156, "height": 45}, "position": {"x": 640, "y": 540}}, {"id": "node-muqbu6ki-s6ib", "data": {"label": "Abstract class dùng để làm class cha (class base) cho các class khác và không khởi tạo instance từ abstract class được", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 960, "y": 495}}, {"id": "node-muqbu6ki-g3r6", "data": {"label": "Sử dụng cú pháp abstract class ClassName {}", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 960, "y": 585}}, {"id": "node-muqbu6ki-tnpq", "data": {"label": "abstract class thì vẫn chứa các thành phần như 1 class bình thường, tuy nhiên nó có thêm 1 thành phần là abstract method, nhằm định nghĩa tên và kiểu dữ liệu trả về (nhưng không có method body) → class con bắt buộc phải định nghĩa các method tương ứng với abstract method của abstract class\\nvd: abstract getFullName(): string;", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 320}, "position": {"x": 1280, "y": 585}}, {"id": "node-muqbu6ki-256i", "data": {"label": "Interface", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#8b5cf6"}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 45}, "position": {"x": 320, "y": 675}}, {"id": "node-muqbu6ki-0wo6", "data": {"label": "Dùng để định nghĩa các thành phần có thể có trong\\nTham số đầu vào của function\\