node-muqbva91-3em4"}, {"id": "edge-node-muqbva91-n4a7-node-muqbva91-cp96", "data": {"color": "#8b5cf6"}, "type": "mindmap", "hidden": false, "source": "node-muqbva91-n4a7", "target": "node-muqbva91-cp96"}, {"id": "edge-node-muqbva91-n4a7-node-muqbva91-u3f2", "data": {"color": "#8b5cf6"}, "type": "mindmap", "hidden": false, "source": "node-muqbva91-n4a7", "target": "node-muqbva91-u3f2"}], "nodes": [{"id": "root", "data": {"label": "RabbitMQ", "isRoot": true, "collapsed": false, "childCount": 6}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 44}, "position": {"x": 0, "y": 0}}, {"id": "node-muqbva90-3wuf", "data": {"label": "Các giao thức trong RabbitMQ", "isRoot": false, "collapsed": false, "childCount": 4, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 310, "height": 45}, "position": {"x": 320, "y": -1350}}, {"id": "node-muqbva90-j9ya", "data": {"label": "Protocol (giao thức) là gì?", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 266, "height": 45}, "position": {"x": 640, "y": -1620}}, {"id": "node-muqbva90-i8c7", "data": {"label": "Giao thức là một đặc tả hay tiêu chuẩn giúp cho các thành phần điện tử giao tiếp với nhau", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 960, "y": -1620}}, {"id": "node-muqbva90-xzjy", "data": {"label": "Thể hiện qua cách thức dữ liệu được gửi theo một tập hợp các quy tắc", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 1280, "y": -1620}}, {"id": "node-muqbva90-matg", "data": {"label": "Các quy tắc này  có thể bao gồm những lệnh nào nên được sử  dụng khi gửi hoặc nhận dữ liệu", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 1600, "y": -1665}}, {"id": "node-muqbva90-v1cu", "data": {"label": "Loại dữ liệu nào có thể được truyền tải và làm thế nào để xác nhận rằng dữ liệu đã được truyền tải thành công", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 1600, "y": -1575}}, {"id": "node-muqbva90-9beo", "data": {"label": "Giao thức AMQP (Advanced Message Queuing Protocal)", "isRoot": false, "collapsed": false, "childCount": 4, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 640, "y": -1350}}, {"id": "node-muqbva90-2mlg", "data": {"label": "Là giao thức được thiết kế để gửi tin nhắn tới một hàng đợi", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 960, "y": -1485}}, {"id": "node-muqbva90-xgr2", "data": {"label": "Tuân theo các quy tắc về cách thức truyền tải thông điệp được định tuyến và lưu trữ trong Broker", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 960, "y": -1395}}, {"id": "node-muqbva90-lyo0", "data": {"label": "Quy định rất cụ thể về cách thiết lập kết nối, hành vi của broker và cách bạn khai báo các hàng đợi", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 960, "y": -1305}}, {"id": "node-muqbva90-893h", "data": {"label": "Dữ liệu truyền trên AMQP là binary", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 352, "height": 45}, "position": {"x": 960, "y": -1215}}, {"id": "node-muqbva90-23wo", "data": {"label": "MQTT", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 45}, "position": {"x": 640, "y": -1125}}, {"id": "node-muqbva90-vinj", "data": {"label": "STOMP", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 45}, "position": {"x": 640, "y": -1035}}, {"id": "node-muqbva90-6sd1", "data": {"label": "Queue", "isRoot": false, "collapsed": false, "childCount": 3, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 45}, "position": {"x": 320, "y": -540}}, {"id": "node-muqbva90-dtzh", "data": {"label": "Là nơi chứa message cho đến khi customer xử lý xong message đó hoặc message đó bị loại bỏ khỏi Queue", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 640, "y": -945}}, {"id": "node-muqbva90-xkih", "data": {"label": "Nó có một vài thuộc tính để xác định cách chúng hoạt động. Các thuộc tính được truyền vào Broker khi khai báo Queue", "isRoot": false, "collapsed": false, "childCount": 5, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 640, "y": -675}}, {"id": "node-muqbva90-rfeq", "data": {"label": "Mỗi 1 Queue sẽ luôn có 1 tên, nếu không được định nghĩa thì sẽ random 1 tên", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 960, "y": -855}}, {"id": "node-muqbva90-3gac", "data": {"label": "Queue durable: sẽ xác định xem Queue có nên tồn tại sau khi Broker khởi động lại không", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 960, "y": -765}}, {"id": "node-muqbva90-9qjh", "data": {"label": "Queue exculsive: nó chỉ sử dụng duy nhất 1 kết nối và khi kết nối đó đóng lại thì Queue đó cũng bị xóa", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 960, "y": -675}}, {"id": "node-muqbva90-11iz", "data": {"label": "auto-delete: Queue sẽ bị xóa khi consumer cuối cùng unsubscribe", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 960, "y": -585}}, {"id": "node-muqbva90-qxe3", "data": {"label": "Ngoài ra thì nó có một vài thuộc tính tùy chọn như TTL: sẽ xóa queue không hoạt động sau bao lâu", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 960, "y": -495}}, {"id": "node-muqbva90-l499", "data": {"label": "Vòng đời của hàng đợi tin nhắn tạm thời", "isRoot": false, "collapsed": false, "childCount": 4, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 640, "y": -270}}, {"id": "node-muqbva90-p62w", "data": {"label": "Client tạo MQ (declare) - Máy chủ (broker) xác nhận (declare-OK)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 960, "y": -405}}, {"id": "node-muqbva90-mtul", "data": {"label": "Client tạo consumer tiêu thụ mesage trong MQ", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 960, "y": -315}}, {"id": "node-muqbva90-hstl", "data": {"label": "Client cancel consumer (trực tiếp cancel consumer hoặc gián tiếp qua việc đóng channel/connection)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 960, "y": -225}}, {"id": "node-muqbva90-6nt3", "data": {"label": "Khi lastest consumer biết mất khỏi MQ, máy chủ sẽ xóa MQ", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 960, "y": -135}}, {"id": "node-muqbva90-6ofa", "data": {"label": "Exchange", "isRoot": false, "collapsed": false, "childCount": 4, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 45}, "position": {"x": 320, "y": 360}}, {"id": "node-muqbva90-qopl", "data": {"label": "Exchange chịu trách nhiệm định tuyến message tới Queue tương ứng", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 640, "y": -45}}, {"id": "node-muqbva90-nvlf", "data": {"label": "Exchange cũng có một vài thuộc tính tương đồng với Queue: độ bền durable, tạm thời (sẽ bị xóa khi RabbitQM bị tắt), auto-delete(sau khi đối tượng được liên kết cuối cùng được gỡ bỏ)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 183}, "position": {"x": 640, "y": 45}}, {"id": "node-muqbva90-w178", "data": {"label": "Vòng đời của Exchange", "isRoot": false, "collapsed": false, "childCount": 3, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 243, "height": 45}, "position": {"x": 640, "y": 225}}, {"id": "node-muqbva90-olzb", "data": {"label": "Client sẽ yêu cầu máy chủ xác nhận xem Exchange có tồn tại hay không. Nếu không thì sẽ được tạo", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 960, "y": 135}}, {"id": "node-muqbva90-7rex", "data": {"label": "Client gửi message tới Exchange", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 325, "height": 45}, "position": {"x": 960, "y": 225}}, {"id": "node-muqbva90-b4dc", "data": {"label": "Client có thể chọn xóa Exchange", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 325, "height": 45}, "position": {"x": 960, "y": 315}}, {"id": "node-muqbva90-787v", "data": {"label": "Có 4 loại exchange khác nhau", "isRoot": false, "collapsed": false, "childCount": 4, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 302, "height": 45}, "position": {"x": 640, "y": 585}}, {"id": "node-muqbva90-bbk2", "data": {"label": "Direct", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 45}, "position": {"x": 960, "y": 405}}, {"id": "node-muqbva90-kwoz", "data": {"label": "Điều hướng chính xác message tới queue với điều kiện:\\nrouting_key trong message == routing_key trong biding", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 1280, "y": 405}}, {"id": "node-muqbva90-avjy", "data": {"label": "Topic", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 45}, "position": {"x": 960, "y": 495}}, {"id": "node-muqbva90-igms", "data": {"label": "Điều hướng message tới các queue có cùng routing_key pattern trong binding", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 1280, "y": 495}}, {"id": "node-muqbva90-t9qs", "data": {"label": "vd:  taxi.*.large", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 167, "height": 45}, "position": {"x": 1600, "y": 495}}, {"id": "node-muqbva90-c1pr", "data": {"label": "Fanout", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 45}, "position": {"x": 960, "y": 585}}, {"id": "node-muqbva90-vnkc", "data": {"label": "Không dùng routing_key, mọi message sẽ được đưa vào tất các các queue đã bind", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 1280, "y": 585}}, {"id": "node-muqbva90-1qcs", "data": {"label": "Headers", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 45}, "position": {"x": 960, "y": 720}}, {"id": "node-muqbva90-gcby", "data": {"label": "Binding sẽ thiết lập thuộc tính x-match = all (hoặc any)\\nvà các thuộc tính khác cần so khớp", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 1280, "y": 720}}, {"id": "node-muqbva90-nvfn", "data": {"label": "x-match = all", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 152, "height": 45}, "position": {"x": 1600, "y": 675}}, {"id": "node-muqbva90-78eo", "data": {"label": "có nghĩa là các thuộc tính trong message header phải khớp toàn bộ với các thuộc tính được binding định nghĩa", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 1920, "y": 675}}, {"id": "node-muqbva90-tj59", "data": {"label": "VD:\\nBinding định nghĩa arguments:\\nx-match = all\\nfrom = New York\\nto = Sydney\\nMessage header\\nfrom = New York\\nto = Sydney\\n⇒ thì message này sẽ được route tới Queue tương ứng\\n⇒ trường hợp 1 giá trị bất kỳ trong header bị lệch thì sẽ không được route", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 375}, "position": {"x": 2240, "y": 675}}, {"id": "node-muqbva90-009w", "data": {"label": "x-match = any", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 163, "height": 45}, "position": {"x": 1600, "y": 765}}, {"id": "node-muqbva90-q0ho", "data": {"label": "có nghĩa là các thuộc tính trong message header chỉ phải khớp một phần với các thuộc tính được binding định nghĩa", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 1920, "y": 765}}, {"id": "node-muqbva90-41ow", "data": {"label": "VD:\\nBinding định nghĩa arguments:\\nx-match = any\\nfrom = New York\\nto = Sydney\\nMessage header\\nfrom = New York\\nto = Hanoi\\n⇒ thì message này sẽ được route tới Queue tương ứng\\n⇒ trường hợp toàn bộ giá trị trong header bị lệch thì sẽ không được route", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 375}, "position": {"x": 2240, "y": 765}}, {"id": "node-muqbva90-awef", "data": {"label": "Binding", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 45}, "position": {"x": 320, "y": 900}}, {"id": "node-muqbva90-29od", "data": {"label": "Là sự kết hợp (hoặc mối liên hệ) giữa Queue và Exchange. Nó mô tả việc Exchange sẽ phân phối message cho Queue nào (dựa trên routing_key / hay còn có thể gọi là binding key)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 183}, "position": {"x": 640, "y": 855}}, {"id": "node-muqbva90-n87u", "data": {"label": "channel.queue_bind(exchange=exchange_name, queue=queue_name, routing_key='black')", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 640, "y": 945}}, {"id": "node-muqbva90-0ji0", "data": {"label": "ACK (acknowledgement)", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 255, "height": 45}, "position": {"x": 320, "y": 1080}}, {"id": "node-muqbva90-7bgm", "data": {"label": "Là cơ chế phản hồi từ customer tới RabbitMQ về việc message đã được xủ lý xong chưa", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 640, "y": 1080}}, {"id": "node-muqbva90-v8v3", "data": {"label": "Auto ACK (ko nên)", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 200, "height": 45}, "position": {"x": 960, "y": 1035}}, {"id": "node-muqbva90-eqiv", "data": {"label": "Ngay sau khi RabbitMQ  gửi message tới customer thì nó tự động đánh dấu là message đã được xử lý thành công và loại bỏ nó ra khỏi queue", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 155}, "position": {"x": 1280, "y": 1035}}, {"id": "node-muqbva90-pyuc", "data": {"label": "Rủi ro mất dữ liệu (ko đảm bảo reliability cho hệ thống) nếu customer gặp sự cố hoặc xử lý message bị lỗi", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 1600, "y": 1035}}, {"id": "node-muqbva90-wept", "data": {"label": "Manual ACK (khuyên dùng)", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 281, "height": 45}, "position": {"x": 960, "y": 1125}}, {"id": "node-muqbva90-07xd", "data": {"label": "Sau khi customer nhận và xử lý xong message, thì mới báo lại sang RabbitMQ", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 1280, "y": 1125}}, {"id": "node-muqbva91-8zbd", "data": {"label": "Nếu customer gặp sự cố hoặc xử lý message lỗi, RabbitMQ hiểu rằng message chưa được xử lý thành công và nó sẽ\\nđưa message quay lại queue (requeue)\\nloại bỏ message đó (discard) - vd: do sai message format , có gửi lại cũng vẫn bị lỗi khi xử lý", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 265}, "position": {"x": 1600, "y": 1125}}, {"id": "node-muqbva91-n4a7", "data": {"label": "vHost (Virtual host)", "isRoot": false, "collapsed": false, "childCount": 6, "branchColor": "#8b5cf6"}, "type": "mindmap", "hidden": false, "measured": {"width": 209, "height": 45}, "position": {"x": 320, "y": 1440}}, {"id": "node-muqbva91-sdk3", "data": {"label": "Dùng để phân tách các môi trường hoạt động khác nhau trên cùng một phiên bản RabbitMQ (trên cùng một máy chủ vật lý)", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#8b5cf6"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 640, "y": 1215}}, {"id": "node-muqbva91-0wp2", "data": {"label": "Do các vHost chỉa sẻ chung một cấu hình máy chủ vật lý nên dù các vHost là độc lập nhưng chúng lại có thể gây ảnh hưởng tới hiệu suất của nhau", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#8b5cf6"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 155}, "position": {"x": 960, "y": 1215}}, {"id": "node-muqbva91-u5dr", "data": {"label": "Nó tạo ra 1 nhóm các logic gồm: connection, exchange, queue, binding, user permission khác nhau trên cùng một phiên bản RabbitMQ", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#8b5cf6"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 640, "y": 1305}}, {"id": "node-muqbva91-xpf5", "data": {"label": "Client kết nối tới RabbitMQ phải chỉ định vHost mà nó sẽ hoạt động trong đó", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#8b5cf6"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 640, "y": 1395}}, {"id": "node-muqbva91-3em4", "data": {"label": "Khi thiết lập RabbitMQ phải có tối thiểu 1 vHost, default vHost là “/“", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#8b5cf6"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 640, "y": 1485}}, {"id": "node-muqbva91-cp96", "data": {"label": "Phải tự thiết lập permission cho user", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#8b5cf6"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 640, "y": 1575}}, {"id": "node-muqbva91-u3f2", "data": {"label": "Một vHost mới được tạo sẽ có một vài Exchange mặc định, nhưng không có các thực thể khác và không có quyền người dùng", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#8b5cf6"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 640, "y": 1665}}], "viewport": {"x": 508, "y": 334.7, "zoom": 0.2}}	2026-10-02 02:12:15.252	2026-10-02 04:00:55.701	cmuqeh88k0001kdidllbuyvta
