 ở giữa", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 181, "height": 45}, "position": {"x": 1920, "y": 45}}, {"id": "node-muqbxicl-gx5p", "data": {"label": "2 con trỏ đối đầu (Start & End pointers)", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 960, "y": 180}}, {"id": "node-muqbxicl-bmd9", "data": {"label": "Sử dụng 2 pointer (start đặt ở đầu và end đặt ở cuối) của linked list\\nThường dùng trong double linked list hoặc mảng (do Single linked list khó xác định prev node)", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 155}, "position": {"x": 1280, "y": 180}}, {"id": "node-muqbxicl-nwyb", "data": {"label": "Ứng dụng", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 45}, "position": {"x": 1600, "y": 180}}, {"id": "node-muqbxicl-tvqy", "data": {"label": "Kiểm tra tính đối xứng", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 236, "height": 45}, "position": {"x": 1920, "y": 135}}, {"id": "node-muqbxicl-pxtd", "data": {"label": "Tìm cặp số có tổng cho trước", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 297, "height": 45}, "position": {"x": 1920, "y": 225}}, {"id": "node-muqbxicl-3h51", "data": {"label": "Con trỏ duy trì khoảng cách (Fixed distance/Window pointers)", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 960, "y": 315}}