vo-uiv2"}], "nodes": [{"id": "root", "data": {"label": "Array", "isRoot": true, "collapsed": false, "childCount": 2}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 44}, "position": {"x": 0, "y": 0}}, {"id": "node-muqbx8vo-i23x", "data": {"label": "Mảng là một kiểu dữ liệu dùng để lưu trữ 1 tập hợp dữ liệu nằm liên tiếp nhau trong 1 vùng nhớ", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 320, "y": -135}}, {"id": "node-muqbx8vo-yt9g", "data": {"label": "Có 2 loại  array", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 168, "height": 45}, "position": {"x": 320, "y": 45}}, {"id": "node-muqbx8vo-njw9", "data": {"label": "Static Array (mảng tĩnh)", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 248, "height": 45}, "position": {"x": 640, "y": -45}}, {"id": "node-muqbx8vo-hx42", "data": {"label": "Mảng có capacity là một số cố định", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 354, "height": 45}, "position": {"x": 960, "y": -45}}, {"id": "node-muqbx8vo-1fmd", "data": {"label": "Dynamic Array (mảng động)", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 289, "height": 45}, "position": {"x": 640, "y": 90}}, {"id": "node-muqbx8vo-t170", "data": {"label": "Mảng không có capacity cố định", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 327, "height": 45}, "position": {"x": 960, "y": 45}}, {"id": "node-muqbx8vo-aana", "data": {"label": "Cụ thể trong JS: khi khai báo mảng và có gán giá trị thì capacity sẽ thường lớn hơn số lượng phần tử của mảng (over-allocation - cấp phát dư thừa - nhưng sẽ ko biết được con số cụ thể)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 183}, "position": {"x": 1280, "y": 45}}, {"id": "node-muqbx8vo-bri3", "data": {"label": "Khi dynamic array đạt tới kích thước tối đa", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 960, "y": 135}}, {"id": "node-muqbx8vo-80qf", "data": {"label": "Tìm vùng nhớ mới có kích thước lớn hơn 1.5 đến 2 lần kích thước của mảng\\nCopy toàn bộ mảng cũ sang vùng nhơ mới\\nThêm phần tử mới vào\\nGarbage collector sẽ thu hồi vùng nhớ cũ", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 238}, "position": {"x": 1280, "y": 135}}, {"id": "node-muqbx8vo-fnvm", "data": {"label": "Trường hợp đặc biệt:\\nNếu không tìm được vùng nhớ mới nào phù hợp với array size cần có", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 1600, "y": 135}}, {"id": "node-muqbx8vo-uiv2", "data": {"label": "Đầu tiên Garbage collector sẽ kích hoạt cơ chế xử lý các vùng nhớ không cần thiết\\nTìm lại vùng nhớ cho array\\nNếu không tìm được thì báo lỗi Out of memory (Trong JS có thể sẽ gặp Heap out of memory", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 210}, "position": {"x": 1920, "y": 135}}], "viewport": {"x": 153, "y": 283.3026315789474, "zoom": 0.5394736842105263}}	2026-10-02 02:13:47.021	2026-10-02 03:26:03.509	cmuqei03p0002kdidk6x7ntfg
