lor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 183}, "position": {"x": 1280, "y": 180}}, {"id": "node-muqbyi84-1rl2", "data": {"label": "Những thành phần không cần thiết trong 1 ứng dụng dùng NodeJS", "isRoot": false, "collapsed": false, "childCount": 4, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 1600, "y": 180}}, {"id": "node-muqbyi84-c7c2", "data": {"label": "devDependencies (jest test, eslint,...)", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 1920, "y": 45}}, {"id": "node-muqbyi84-g364", "data": {"label": "giúp giảm dung lượng, tăng cường bảo mật", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 2240, "y": 45}}, {"id": "node-muqbyi84-qsey", "data": {"label": "mã nguồn chứa cả ts files, trong khi chỉ cần các file .js (sau khi compile) nằm trong dist folder", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 1920, "y": 135}}, {"id": "node-muqbyi84-yrm1", "data": {"label": "giảm dung lượng, tránh lộ logic", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 320, "height": 45}, "position": {"x": 2240, "y": 135}}, {"id": "node-muqbyi84-vs61", "data": {"label": "build tools (npm), npm cache", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 298, "height": 45}, "position": {"x": 1920, "y": 225}}, {"id": "node-muqbyi84-vcwj", "data": {"label": "Giảm dung lượng", "isRoot": false, "collapsed": 