ocker volumes ls", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 194, "height": 45}, "position": {"x": 1280, "y": 855}}, {"id": "node-muqbyi84-mq2j", "data": {"label": "liệt kê các volumes", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 203, "height": 45}, "position": {"x": 1600, "y": 855}}, {"id": "node-muqbyi84-rwg5", "data": {"label": "docker volume inspect <volume_name>", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 1280, "y": 945}}, {"id": "node-muqbyi84-knqf", "data": {"label": "Xem đường dẫn tới volume", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 281, "height": 45}, "position": {"x": 1600, "y": 945}}, {"id": "node-muqbyi84-kd5h", "data": {"label": "docker volume prune", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 225, "height": 45}, "position": {"x": 1280, "y": 1035}}, {"id": "node-muqbyi84-g8s2", "data": {"label": "Xóa tất cả các volume không được sử dụng", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 1600, "y": 1035}}, {"id": "node-muqbyi84-e7as", "data": {"label": "Bind mounts", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 147, "height": 45}, "position": {"x": 640, "y": 1125}}, {"id": "node-muqbyi84-mcsn", "data": {"label": "Ánh xạ 1 vùng lưu trữ bên ngoài máy host vào trong container", "isRoot": false, "collapsed": false, "childCount"