n": {"x": 960, "y": -1935}}, {"id": "node-muqbysmb-a39b", "data": {"label": "Tự hồi phục (Self-healing)", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 267, "height": 45}, "position": {"x": 1280, "y": -2070}}, {"id": "node-muqbysmb-bt7h", "data": {"label": "Tự động khởi động lại các container bị lỗi, thay thế và xóa các container không phản hồi - đảm bảo ứng dụng luôn “sống”", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 1600, "y": -2070}}, {"id": "node-muqbysmb-rlx4", "data": {"label": "Tự động mở rộng (auto-scaling)", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 323, "height": 45}, "position": {"x": 1280, "y": -1980}}, {"id": "node-muqbysmb-ipoh", "data": {"label": "Tự động tăng hoặc giảm các container nhằm đám ứng tải cho ứng dụng giúp tiết kiệm tài nguyên", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 1600, "y": -1980}}, {"id": "node-muqbysmb-h1a7", "data": {"label": "Quản lý cấu hình và bí mật", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 274, "height": 45}, "position": {"x": 1280, "y": -1890}}, {"id": "node-muqbysmb-dbdd", "data": {"label": "Quản lý các thông tin nhạy cảm, bảo mật mà không cần phải build lại container’s imange", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 1600, "y": -1890}}, {"id": "node-muqbysmb-ktoe", "data": {"label": "Cân bằng tải (load balancing)", "isRoot": false, "col