ysmb-1uyl", "data": {"label": "etcd", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 45}, "position": {"x": 960, "y": -1530}}, {"id": "node-muqbysmb-2rup", "data": {"label": "Được cọi như là “bộ nhớ” của hệ thống, nó lưu trữ toàn bộ dữ liệu cấu hình, trạng thái của cụm dưới dạng key-value", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 1280, "y": -1530}}, {"id": "node-muqbysmb-d52e", "data": {"label": "scheduler", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 45}, "position": {"x": 960, "y": -1440}}, {"id": "node-muqbysmb-cavb", "data": {"label": "Được coi như là “người điều phối”, nó theo dõi các Pod mới được tạo và sẽ quyết định đặt pod đó vào trong node nào dựa trên yêu cầu tài nguyên", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 155}, "position": {"x": 1280, "y": -1440}}, {"id": "node-muqbysmb-p5tn", "data": {"label": "controller manager", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 206, "height": 45}, "position": {"x": 960, "y": -1350}}, {"id": "node-muqbysmb-6938", "data": {"label": "Đảm nhận việc giám sát trạng thái của cluster,  liên tục theo dõi để đưa trạng thái hệ thống về đúng trạng thái mong muốn (vd: 1 pod bị xóa thì nó sẽ ra lệnh để tạo mới pod để thay thế)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 183}, "position": {"x": 1280, "y": -1350}}, {"id": "node-muqbysmb-cb0r", "data": {"label": "Node (1 hoặc nhiều)", "isRoot": false, "collapsed": false, "childCount": 3, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 214, "height": 45}, "position": {"x": 640, "y": -1170}}, {"id": "node-muqbysmb-tebh", "data": {"label": "kubelet", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 45}, "position": {"x": 960, "y": -1260}}, {"id": "node-muqbysmb-cd50", "data": {"label": "nhận yêu cầu từ  kube-api-server để thực thi các pod trên node", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 1280, "y": -1260}}, {"id": "node-muqbysmb-yz69", "data": {"label": "kube-proxy", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 45}, "position": {"x": 960, "y": -1170}}, {"id": "node-muqbysmb-etft", "data": {"label": "Là thành phần network chạy trên node cho phép các pod giao tiếp với nhau và giao tiếp ra bên ngoài", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 1280, "y": -1170}}, {"id": "node-muqbysmb-e8b3", "data": {"label": "pod (1 hoặc nhiều)", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 200, "height": 45}, "position": {"x": 960, "y": -1080}}, {"id": "node-muqbysmb-u6re", "data": {"label": "pod chính là đơn vị nhỏ nhất trong K8S - thường 1 pod sẽ tương ứng với 1 container (tuy nhiên có thể chạy nhiều container trong 1 pod)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {