, "type": "mindmap", "hidden": false, "measured": {"width": 326, "height": 45}, "position": {"x": 640, "y": -2115}}, {"id": "node-muqbrxtx-4s0g", "data": {"label": "Code JS được đưa lần lượt từ trên xuống dưới vào Callstack (thuộc V8)", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 960, "y": -2430}}, {"id": "node-muqbrxtx-emc2", "data": {"label": "Đi sâu hơn 1 chút", "isRoot": false, "collapsed": false, "childCount": 5, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 188, "height": 45}, "position": {"x": 1280, "y": -2430}}, {"id": "node-muqbrxtx-oh5g", "data": {"label": "V8 nhận toàn bộ mã nguồn file js dưới dạng chuỗi (string)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 1600, "y": -2880}}, {"id": "node-muqbrxtx-67o4", "data": {"label": "V8 (Scanner & Parser) phân tích cú pháp thành các token (từ khóa, biến, toán tử)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 1600, "y": -2790}}, {"id": "node-muqbrxtx-q4b9", "data": {"label": "V8 dựng các tokens này thành cây trừu tượng (AST - Abstract syntax tree) để đại diện cho cấu trúc logic của chương trình", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 1600, "y": -2655}}, {"id": "node-muqbrxtx-bmen", "data": {"label": "ví dụ với đoạn mã sau\\nconst x = 5 + a;", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 231, "height": 73}, "position": {"x": 1920, "y": -2655}}, {"id": "node-muqbrxtx-xtlp", "data": {"label": "Dạng text:\\nVariableDeclaration (const)\\n└── VariableDeclarator\\n├── Identifier (name: \\"x\\")\\n└── BinaryExpression (operator: \\"+\\")\\n├── NumericLiteral (value: 5)\\n└── Identifier (name: \\"a\\")", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 238}, "position": {"x": 2240, "y": -2700}}, {"id": "node-muqbrxtx-9gr0", "data": {"label": "Dạng JSON:\\n{\\n\\"type\\": \\"VariableDeclaration\\",\\n\\"kind\\": \\"const\\",\\n\\"declarations\\": [\\n{\\n\\"type\\": \\"VariableDeclarator\\",\\n\\"id\\": { \\"type\\": \\"Identifier\\", \\"name\\": \\"x\\" },\\n\\"init\\": {\\n\\"type\\": \\"BinaryExpression\\",\\n\\"operator\\": \\"+\\",\\n\\"left\\": { \\"type\\": \\"NumericLiteral\\", \\"value\\": 5 },\\n\\"right\\": { \\"type\\": \\"Identifier\\", \\"name\\": \\"a\\" }\\n}\\n}\\n]\\n}", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 568}, "position": {"x": 2240, "y": -2610}}, {"id": "node-muqbrxtx-ryej", "data": {"label": "V8 dùng JIT (just in time) - trình biên dịch để biên dịch cây AST sang bytecode", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 1600, "y": -2340}}, {"id": "node-muqbrxtx-m542", "data": {"label": "Bytecode là gì?", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 169, "height": 45}, "position": {"x": 1920, "y": -2475}}, {"id": "node-muqbrxtx-dw24", "data": {"label": "Bytecode là một dạng mã trung gian (nằm giữa mã bậc cao JS và mã máy)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 2240, "y": -2520}}, {"id": "node-muqbrxtx-hikd", "data": {"label": "Bytecode không phụ thuộc vào phần cứng cụ thể nào (chip Intel hay AMD) mà nó là dạng mã dành riêng cho một máy ảo của V8 (Ignitioin)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 155}, "position": {"x": 2240, "y": -2430}}, {"id": "node-muqbrxtx-szr2", "data": {"label": "Tại sao cần Bytecode?", "isRoot": false, "collapsed": false, "childCount": 3, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 231, "height": 45}, "position": {"x": 1920, "y": -2250}}, {"id": "node-muqbrxtx-8w78", "data": {"label": "Giúp chương trình chạy ngay lập tức mà không cần phải biên dịch sang mã máy", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 2240, "y": -2340}}, {"id": "node-muqbrxtx-e9x7", "data": {"label": "Bytecode nhẹ hơn rất nhiều so với mã máy", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 2240, "y": -2250}}, {"id": "node-muqbrxtx-xa8r", "data": {"label": "Chỉ có đoạn mã nào chạy lại nhiều lần thì mới cần dịch sang mã máy để tối ưu tốc độ chạy", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 2240, "y": -2160}}, {"id": "node-muqbrxtx-4mnf", "data": {"label": "Đưa code vào Callstack", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 241, "height": 45}, "position": {"x": 1600, "y": -2025}}, {"id": "node-muqbrxtx-fn0b", "data": {"label": "V8 tạo ra 1 Global Excution Context (tạo duy nhất 1 lần khi chạy chương trình)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 1920, "y": -2070}}, {"id": "node-muqbrxtx-4pew", "data": {"label": "Nếu gặp function, V8 tạo ra 1 Function Excution Context rồi đưa vào trong Callstack", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 1920, "y": -1980}}, {"id": "node-muqbrxtx-nbqp", "data": {"label": "Nếu đoạn mã là ĐỒNG BỘ, V8 thực thi ngay, sau đó xóa đoạn mã đó khỏi Callstack", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 960, "y": -1890}}, {"id": "node-muqbrxtx-71z6", "data": {"label": "Nếu đoạn mã là BẤT ĐỒNG BỘ, V8 chuyển sang cho lớp NodeJs bindings xử lý (thư viện libuv hay OS), sau đó xóa đoạn mã đó khỏi Callstack", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 155}, "position": {"x": 960, "y": -1800}}, {"id": "node-muqbrxtx-glbw", "data": {"label": "Libuv xử lý các task bất đồng bộ đó và đưa callback của chúng vào các queue tương ứng (gọi chung là Event queue hoặc Callback queue):\\nNextTick queue: chứa callback của process.nextTick()\\nMicro-task queue chứa callback của: async/await, Promise,...\\nMarcro-task queue chứa các callback còn lại (vd: callback của setTimeout, setInterval, setImmediate và các I/O callback như đọc/ghi file, network...)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 375}, "position": {"x": 960, "y": -1710}}, {"id": "node-muqbrxtx-hxek", "data": {"label": "Event loop đứng giữa Call-stack và Callback queue.\\nEvent loop liên tục kiểm tra tình trạng của call stack, nếu call stack trống, nó sẽ đưa callback vào trong callstack để xử lý (thứ tự callback đưa vào theo thứ tự ưu tiên trong mục 4 ở trên)", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 238}, "position": {"x": 960, "y": -1620}}, {"id": "node-muqbrxtx-v7ve", "data": {"label": "Một điểm lưu ý: là sau mỗi 1 callback (của Marcro-task) được đưa vào Call-stack để xử lý thì sau đó Event loop sẽ xem có callback của NextTick hay Micro-task còn không, thì nó sẽ ưu tiên đưa tiếp các callback đó vào trước khi lại đưa callback của Marcro-task vào tiếp.", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 265}, "position": {"x": 1280, "y": -1620}}, {"id": "node-muqbrxtx-pb2r", "data": {"label": "Chương trình sẽ dừng lại khi thỏa mãn đồng thời các điều kiện", "isRoot": false, "collapsed": false, "childCount": 3, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 960, "y": -1440}}, {"id": "node-muqbrxtx-8ucg", "data": {"label": "Call-stack trống", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 175, "height": 45}, "position": {"x": 1280, "y": -1530}}, {"id": "node-muqbrxtx-7w8i", "data": {"label": "NextTick queue & Micro-task queue trống", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 1280, "y": -1440}}, {"id": "node-muqbrxtx-ybw2", "data": {"label": "Event loop không còn công việc:\\nBất đồng bộ đếm giờ (setTimeout, setInterval, ...)\\nI/O request (đọc file, network request,...)\\nKết nối đang lắng nghe (Http server như server.listen() trong expressjs/nestjs, Socket)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 238}, "position": {"x": 1280, "y": -1350}}, {"id": "node-muqbrxtx-90ha", "data": {"label": "NodeJS - single-thread", "isRoot": false, "collapsed": false, "childCount": 3, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 240, "height": 45}, "position": {"x": 320, "y": -855}}, {"id": "node-muqbrxtx-a13s", "data": {"label": "Chú ý phân biệt giữa core, thread vật lý, process và software thread", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 640, "y": -1215}}, {"id": "node-muqbrxtx-bvhe", "data": {"label": "Core/Luồng vật lý: bản chất là không có luồng vật lý, 1 CPU 4 nhân 8 luồng thực ra là 4 core vật lý (physical core) + 4 core ảo (Logical core) nhằm đánh lừa OS là CPU có 8 core để xử lý", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 183}, "position": {"x": 960, "y": -1260}}, {"id": "node-muqbrxtx-x7mh", "data": {"label": "process: 1 chương trình (vd: nodejs) chạy thì sinh ra 1 tiến trình với 1 port", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 960, "y": -1170}}, {"id": "node-muqbrxtx-00y9", "data": {"label": "software thead: Trong tiến trình thì sẽ chứa các threads để thực hiện các nhiệm vụ trong ứng dụng. Các threads này chia sẻ bộ nhớ của process nhưng độc lập thực thi các logic khác nhau", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 183}, "position": {"x": 1280, "y": -1170}}, {"id": "node-muqbrxtx-jh8y", "data": {"label": "NodeJS chỉ chạy trên 1 luồng vật lý, tuy nhiên nó sử dụng 7 (có thể thay đổi dựa vào số lượng threads trong libuv) OS threads để xử lý", "isRoot": false, "collapsed": false, "childCount": 3, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 640, "y": -945}}, {"id": "node-muqbrxtx-s49k", "data": {"label": "1 main thread: sử dụng để thực thi mã Javascript", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 960, "y": -1080}}, {"id": "node-muqbrxtx-kwue", "data": {"label": "4 threads (libuv) để xử lý I/O bất đồng bộ (hệ thống files, DNS,...) - số lượng thread ở libuv có thể thay đổi (tối đa 128)", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 960, "y": -945}}, {"id": "node-muqbrxtx-oyjl", "data": {"label": "I/O là gì? I/O là hoạt động trao đổi dữ liệu giữa CPU/RAM với các thiết bị bên ngoài. Có 2 loại I/O phổ biến trong NodeJS", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 1280, "y": -945}}, {"id": "node-muqbrxtx-13ic", "data": {"label": "File I/O: Gửi/nhận/mã hóa dữ liệu trong các files trên máy chủ (sử dụng THREAD POOL)", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 1600, "y": -990}}, {"id": "node-muqbrxtx-3k5l", "data": {"label": "Khi có 1 File I/O, thì libuv sẽ chuyển vào 1 thread phụ trong các thread pool để xử lý, lúc này main thread (Event loop) sẽ rảnh và tiếp nhận các yêu cầu khác, khi có kết quả thread phụ nó sẽ đẩy vào Event loop để trả về qua callback", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 210}, "position": {"x": 1920, "y": -990}}, {"id": "node-muqbrxtx-bf1h", "data": {"label": "Network I/O: Gửi/nhận dữ liệu qua internet (API, DB, Socket) (sử dụng MAIN THREAD, chứ ko dùng THREAD POOL)", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 1600, "y": -900}}, {"id": "node-muqbrxtx-3uj3", "data": {"label": "Khi có 1 Network I/O, thì libuv sẽ chuyển yêu cầu này trực tiếp tới Kernal của hệ điều hành, và sau khi thực hiện xong, HĐH sẽ trả lại kết quả cho libuv để thực hiện tiếp (thông qua cơ chế thông báo sự kiện của HĐH)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 210}, "position": {"x": 1920, "y": -900}}, {"id": "node-muqbrxtx-us3u", "data": {"label": "2 threads (V8) dùng để dọn dẹp bộ nhớ (garbage collector) và biên dịch JIT (complier)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 960, "y": -810}}, {"id": "node-muqbrxtx-6w70", "data": {"label": "NodeJS chỉ sử dụng 1 luồng vật lý, vấn đề đặt ra là nếu CPU có nhiều luồng thì gây ra lãng phí, giải pháp là gì?", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 640, "y": -585}}, {"id": "node-muqbrxtx-nw0f", "data": {"label": "Có thể sử dụng các modules: child_process, cluster và worker_threads", "isRoot": false, "collapsed": false, "childCount": 3, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 960, "y": -630}}, {"id": "node-muqbrxtx-ichl", "data": {"label": "cluster: sử dụng để nhân bản process chính (đang chạy nodejs web server) thành các tiến trình khác nhưng dùng chung PORT để scale khả năng xử lý của web server", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 155}, "position": {"x": 1280, "y": -720}}, {"id": "node-muqbrxtx-fg2y", "data": {"label": "worker_threads: sử dụng để chia nhỏ việc nặng, khi main thread nhận 1 công việc nặng, thì sẽ đẩy sang cho worker xử lý (sẽ chạy trên 1 thread khác) và main thread sẽ ko bị block", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 183}, "position": {"x": 1280, "y": -630}}, {"id": "node-muqbrxtx-fq28", "data": {"label": "Lưu ý: Không nên sử dụng worker threads cho các tác vụ như đọc file, lấy dữ liệu từ DB, vì nodejs đã xử lý tốt các nhiệm vụ này rồi (libuv). Chỉ nên dùng cho những tác vụ như mã hóa, bài toán tính toán nặng như ma trận, hay nén file...", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 210}, "position": {"x": 1600, "y": -630}}, {"id": "node-muqbrxtx-v16t", "data": {"label": "child_process: tạo ra 1 process mới độc lập với process đang chạy nodejs. Nó là độc lập nên sẽ chỉ dành cho việc thực thi các nhiệm vụ ngoài như chạy 1 file .exe hay python, hay như chạy các script", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 183}, "position": {"x": 1280, "y": -540}}, {"id": "node-muqbrxtx-lmsb", "data": {"label": "Trong thực tế nếu triển khai microservices qua docker & k8s thì hầu như sẽ không sử dụng cluster và workder. Lúc này k8s sẽ quản lý và sử dụng tài nguyên để xử lý công việc, cũng tránh việc phải quản lý thủ công theo cluster & worker", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 238}, "position": {"x": 960, "y": -450}}, {"id": "node-muqbrxtx-u9wj", "data": {"label": "Blocking I/O và Non-blocking I/O", "isRoot": false, "collapsed": false, "childCount": 3, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 336, "height": 45}, "position": {"x": 320, "y": -225}}, {"id": "node-muqbrxtx-ew1v", "data": {"label": "I/O là gì? I/O là hoạt động trao đổi dữ liệu giữa CPU/RAM với các thiết bị bên ngoài. Có 2 loại I/O phổ biến trong NodeJS (tìm hiểu thêm trong phần NodeJS - single-thread)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 155}, "position": {"x": 640, "y": -360}}, {"id": "node-muqbrxtx-lqif", "data": {"label": "Blocking I/O", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 145, "height": 45}, "position": {"x": 640, "y": -270}}, {"id": "node-muqbrxtx-zj7o", "data": {"label": "Khi 1 I/O request được gọi (vd: đọc file, call API, DB...) thì toàn bộ chương trình sẽ chờ đến khi request đó được trả ra kết quả rồi mới tiếp tục xử lý các request khác", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 155}, "position": {"x": 960, "y": -270}}, {"id": "node-muqbrxtx-fg56", "data": {"label": "Non-blocking I/O", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 192, "height": 45}, "position": {"x": 640, "y": -135}}, {"id": "node-muqbrxtx-q7si", "data": {"label": "Ngược lại với Blocking I/O, khi I/O request được goị, chương trình sẽ không đợi kết quả của nó mà thay vào đó chương trình tiếp tục xử lý các request khác, khi nào có kết quả của I/O request đó thì sẽ trả về cho chương trình xử lý tiếp.", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 210}, "position": {"x": 960, "y": -180}}, {"id": "node-muqbrxtx-nar5", "data": {"label": "NodeJS sử dụng cơ chế Non-blocking I/O thông qua Event loop để xử lý bất đồng bộ", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 960, "y": -90}}, {"id": "node-muqbrxtx-w99w", "data": {"label": "Synchronous (Đồng bộ) và Asynchronous (Bất đồng bộ)", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 320, "y": 225}}, {"id": "node-muqbrxtx-0y03", "data": {"label": "Synchronous (Đồng bộ)", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 247, "height": 45}, "position": {"x": 640, "y": 90}}, {"id": "node-muqbrxtx-n04i", "data": {"label": "Là quá trình xử lý tuần tự từng task (nhiệm vụ) trong 1 chương trình. Task số 1 chạy xong thì mới tới task số 2,... đến hết chương trình.", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 960, "y": 90}}, {"id": "node-muqbrxtx-kxai", "data": {"label": "Ưu điểm", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 45}, "position": {"x": 1280, "y": 0}}, {"id": "node-muqbrxtx-uyen", "data": {"label": "Viết và debug code dễ", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 235, "height": 45}, "position": {"x": 1600, "y": 0}}, {"id": "node-muqbrxtx-k3u4", "data": {"label": "Nhược điểm", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 144, "height": 45}, "position": {"x": 1280, "y": 135}}, {"id": "node-muqbrxtx-agsa", "data": {"label": "Thời gian chạy chương trình lâu", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 321, "height": 45}, "position": {"x": 1600, "y": 90}}, {"id": "node-muqbrxtx-sg8v", "data": {"label": "Dễ block luồng chạy do phải chờ 1 task nặng", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 1600, "y": 180}}, {"id": "node-muqbrxtx-8r7a", "data": {"label": "Asynchronous (Bất đồng bộ)", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 291, "height": 45}, "position": {"x": 640, "y": 360}}, {"id": "node-muqbrxtx-18vr", "data": {"label": "Là quá trình xử lý không đồng bộ các tasks trong 1 chương trình. Các tasks sau được chạy ngay mà không phải chờ task trước đó hoàn thành.", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 960, "y": 360}}, {"id": "node-muqbrxtx-bp3f", "data": {"label": "Ưu điểm", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 45}, "position": {"x": 1280, "y": 315}}, {"id": "node-muqbrxtx-p9ap", "data": {"label": "Thời gian chạy chương trình nhanh", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 350, "height": 45}, "position": {"x": 1600, "y": 270}}, {"id": "node-muqbrxtx-989k", "data": {"label": "Tránh việc block luồng chạy khi gặp các tasks nặng", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 1600, "y": 360}}, {"id": "node-muqbrxtx-argk", "data": {"label": "Nhược điểm", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 144, "height": 45}, "position": {"x": 1280, "y": 450}}, {"id": "node-muqbrxtx-a1p3", "data": {"label": "Viết và debug code phức tạp hơn", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "measured": {"width": 334, "height": 45}, "position": {"x": 1600, "y": 450}}, {"id": "node-muqbrxtx-e6fb", "data": {"label": "Event loop", "isRoot": false, "collapsed": false, "childCount": 3, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 45}, "position": {"x": 320, "y": 1350}}, {"id": "node-muqbrxtx-7756", "data": {"label": "Event loop (vòng lặp sự kiện) là gì?", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 349, "height": 45}, "position": {"x": 640, "y": 585}}, {"id": "node-muqbrxtx-59vc", "data": {"label": "Event loop (vòng lặp sự kiên) cho phép nodejs thực hiện các thao tác non-blocking I/O bằng cách chuyển các thao tác đó sang kernal (nhân hệ thống) bất cứ khi nào có thể\\nKhi thao tác này được hoàn thành, kernal sẽ báo cho NodeIs để thêm callback xử lý tiếp theo vào trong hàng đợi thăm dò (poll queue)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 265}, "position": {"x": 960, "y": 540}}, {"id": "node-muqbrxtx-08r6", "data": {"label": "Một chu kỳ của event loop được gọi là 1 tick", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 960, "y": 630}}, {"id": "node-muqbrxtx-86u9", "data": {"label": "process.nextTick() dùng để gọi một hàm callback ngay sau khi các đoạn mã ĐỒNG BỘ chạy xong, và chạy trước tất cả các đoạn mã BẤT ĐỒNG BỘ khác (có thể hiểu là trước khi Event loop chạy sang các phase tiếp theo)", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 210}, "position": {"x": 1280, "y": 630}}, {"id": "node-muqbrxtx-1std", "data": {"label": "Nó tạo ra NextTick  queue một hàng đợi do NodeJS quản lý (khác với micro task queue do V8 quản lý)\\nVà những callback nằm trong NextTick queue có độ ưu tiên cao nhất hơn cả micro task queue", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 183}, "position": {"x": 1600, "y": 630}}, {"id": "node-muqbrxtx-g01u", "data": {"label": "Các thành phần chính trong Event loop", "isRoot": false, "collapsed": false, "childCount": 5, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 640, "y": 900}}, {"id": "node-muqbrxtx-5f14", "data": {"label": "Call stack", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 45}, "position": {"x": 960, "y": 720}}, {"id": "node-muqbrxtx-a1fg", "data": {"label": "Các mã js sẽ được đưa vào đây đầu tiên", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 1280, "y": 720}}, {"id": "node-muqbrxtx-nj4j", "data": {"label": "Node APIs (nếu code FE thì đây nó sẽ là Web APIs)", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 960, "y": 810}}, {"id": "node-muqbrxtx-fh56", "data": {"label": "Nơi xử lý các tác vụ bất đồng bộ (đọc file, setTimeout, fetch api,...)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 1280, "y": 810}}, {"id": "node-muqbrxtx-mki4", "data": {"label": "Callback queue/ Task queue/ Marcro task queue (hàng đợi tác vụ)", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 960, "y": 900}}, {"id": "node-muqbrxtx-6ycc", "data": {"label": "Nơi chứa các callback fn đã xử lý xong từ Node APIs để chờ đưa vào Call stack để xử lý", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 1280, "y": 900}}, {"id": "node-muqbrxtx-6n4f", "data": {"label": "Micro task queue (hàng đợi vi tác vụ)", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 960, "y": 990}}, {"id": "node-muqbrxtx-8ias", "data": {"label": "Nơi chứa các tác vụ bất đồng bộ có độ ưu tiên cao hơn như:\\nPromise (.then, .catch, .finally) / Async-await\\nqueueMicrotask(): tự thêm 1 tác vụ vào micro task queue", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 183}, "position": {"x": 1280, "y": 990}}, {"id": "node-muqbrxtx-o136", "data": {"label": "Micro task sẽ được đưa vào Callstack trước toàn bộ callback nằm trong callback queue", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 1600, "y": 990}}, {"id": "node-muqbrxtx-k9jz", "data": {"label": "vd dễ hiểu là promise luôn được thực thi trước các node api như setTimeout, hay xử lý file...)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 1920, "y": 990}}, {"id": "node-muqbrxtx-uy04", "data": {"label": "NextTick queue", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 174, "height": 45}, "position": {"x": 960, "y": 1080}}, {"id": "node-muqbrxtx-2g70", "data": {"label": "Nơi chứa các tác vụ bất đồng bộ có độ ưu tiên cao hơn như:\\nprocess.nextTick()", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 1280, "y": 1080}}, {"id": "node-muqbrxtx-kunu", "data": {"label": "Event loop hoạt động như thế nào?", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 353, "height": 45}, "position": {"x": 640, "y": 1665}}, {"id": "node-muqbrxtx-1hyb", "data": {"label": "Các phases chính trong event loop\\n(bản chất đều là các queue - FIFO)", "isRoot": false, "collapsed": false, "childCount": 6, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 345, "height": 73}, "position": {"x": 960, "y": 1620}}, {"id": "node-muqbrxtx-lhzc", "data": {"label": "Timers: Thực thi các hàm callback của setTimout và setInterval", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 1280, "y": 1170}}, {"id": "node-muqbrxtx-8w5c", "data": {"label": "Tại đây, event loop sẽ kiểm tra thời gian chờ đã đặt chưa để thực thi callback", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 1600, "y": 1170}}, {"id": "node-muqbrxtx-5wgw", "data": {"label": "Pending callback: Thực thi các hàm callback của vòng lặp trước", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 1280, "y": 1350}}, {"id": "node-muqbrxtx-nr4p", "data": {"label": "(Trước đây còn gọi là I/O callback). Hầu hết các nhiệm vụ I/O callbacks đều được thực thi ở Poll phase, tuy nhiên có những trường hợp ngoại lệ mà hệ thống (OS) muốn trì hoãn việc thực thi callback sang vòng lặp tiếp theo thì sẽ đưa vào pending callback phase này", "isRoot": false, "collapsed": false, "childCount": 3, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 238}, "position": {"x": 1600, "y": 1350}}, {"id": "node-muqbrxtx-7yos", "data": {"label": "Lỗi kết nối mạng TCP", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 224, "height": 45}, "position": {"x": 1920, "y": 1260}}, {"id": "node-muqbrxtx-tfy8", "data": {"label": "Poll phase bị tràn từ vòng lặp trước, thì sẽ đẩy sang pending", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 1920, "y": 1350}}, {"id": "node-muqbrxtx-zb63", "data": {"label": "Một số trường hợp khi ghi dữ liệu vào stream và bị đầy buffer", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 1920, "y": 1440}}, {"id": "node-muqbrxtx-d2vs", "data": {"label": "Idle, Prepare: Thực thi nội bộ hệ thống (không can thiệp)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 1280, "y": 1530}}, {"id": "node-muqbrxtx-4q0w", "data": {"label": "Poll: Giai đoạn quan trọng nhất - Thực thi các hàm callback của I/O (đọc file, kết nối DB, tiếp nhận http request...)", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 1280, "y": 1755}}, {"id": "node-muqbrxtx-unce", "data": {"label": "Nếu có callback thì Nodejs sẽ chạy hết các callback (hoặc chạy tới giới hạn - còn lại sẽ đẩy vào Pending callback phase)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 1600, "y": 1620}}, {"id": "node-muqbrxtx-lxvj", "data": {"label": "Nếu không có callback thì event loop sẽ đứng tại đây để chờ các sự kiện I/O mới xuất hiện", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 1600, "y": 1800}}, {"id": "node-muqbrxtx-dirk", "data": {"label": "Vậy nó sẽ đứng lại đây đến bao giờ", "isRoot": false, "collapsed": false, "childCount": 3, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 352, "height": 45}, "position": {"x": 1920, "y": 1800}}, {"id": "node-muqbrxtx-c78a", "data": {"label": "có setImmediate đang chờ xử lý ở Check phase\\nhay có callback đang chờ xử lý ở Close callback phase", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 2240, "y": 1710}}, {"id": "node-muqbrxtx-q0nt", "data": {"label": "nếu check phase và close callback phase trông, thì nó sẽ tính toán thời gian nhỏ nhất mà timer phase chờ để xử lý thì nó sẽ đứng lại tại poll phase bằng thời gian đó sau đó sẽ nhảy sang timer phase để xử lý", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 183}, "position": {"x": 2240, "y": 1800}}, {"id": "node-muqbrxtx-ny20", "data": {"label": "nếu timer phase cũng trống thì nó sẽ đợi ở Poll phase vô thời hạn", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 2240, "y": 1890}}, {"id": "node-muqbrxtx-28u5", "data": {"label": "Check: Thực thi các hàm callback của setImmediate", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 1280, "y": 1980}}, {"id": "node-muqbrxtx-w8mb", "data": {"label": "setImmediate: được sử dụng khi muốn thực thi một đoạn code bất đồng bộ nào đó một cách sớm nhất có thể", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 1600, "y": 1980}}, {"id": "node-muqbrxtx-e8oc", "data": {"label": "Bất kỳ hàm nào được truyền làm đối số của setImmediate() thì đều được chạy trong event loop tiếp theo", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 1920, "y": 1980}}, {"id": "node-muqbrxtx-j3ns", "data": {"label": "Close callback: Thực thi các hàm callback của những sự kiện đóng (ví dụ: socket.on(‘close’, ...) )", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 1280, "y": 2070}}, {"id": "node-muqbrxtx-umay", "data": {"label": "Cách thức thực thi", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 198, "height": 45}, "position": {"x": 960, "y": 2160}}, {"id": "node-muqbrxtx-rp79", "data": {"label": "Event loop thực thi tuần tự các phase (như đã đề cập ở trên):\\nxử lý các callback nằm trong các phase queue tới khi phase queue đó hết callback (hoặc đạt tới giới hạn xử lý tối đa) thì nó sẽ chuyển tiếp tới phase tiếp theo và cứ thế tiếp diễn", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#06b6d4"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 238}, "position": {"x": 1280, "y": 2160}}, {"id": "node-muqbrxtx-se2y", "data": {"label": "Buffer", "isRoot": false, "collapsed": false, "childCount": 5, "branchColor": "#8b5cf6"}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 45}, "position": {"x": 320, "y": 2610}}, {"id": "node-muqbrxtx-68jv", "data": {"label": "Buffer: là 1 vùng nhớ dùng để lưu dữ liệu nhị phân (nằm ngoài V8 heap - không bị quản lý bởi cơ chế dọn rác của V8)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#8b5cf6"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 640, "y": 2250}}, {"id": "node-muqbrxtx-23ao", "data": {"label": "Trước kia JS làm việc với trình duyệt nên hầu hết sử dụng dữ liệu là String. Tuy nhiên web server NodeJS làm việc cả với file, image, video... nên buffer sinh ra để làm việc với các dữ liệu nhị phân này hiệu quả", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#8b5cf6"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 210}, "position": {"x": 640, "y": 2340}}, {"id": "node-muqbrxtx-xvbn", "data": {"label": "Tại sao nên sử dụng Buffer", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#8b5cf6"}, "type": "mindmap", "hidden": false, "measured": {"width": 275, "height": 45}, "position": {"x": 640, "y": 2475}}, {"id": "node-muqbrxtx-0w6o", "data": {"label": "Hiệu năng cao hơn so với String, bởi vì xử lý string trong JS tốn ram hơn do là mỗi ký tự chiếm nhiều byte hơn", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#8b5cf6"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 960, "y": 2430}}, {"id": "node-muqbrxtx-vfxf", "data": {"label": "Độ chính xác cao như việc đọc 1 file ảnh nhị phân rồi chuyển thành String, khi đó xuất hiện 1 số byte không hợp lệ trong bảng mã UTF-8 thì các byte đó sẽ bị biến đổi hoặc mất đi, dẫn đến file ảnh ban đầu bị hỏng", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#8b5cf6"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 210}, "position": {"x": 960, "y": 2520}}, {"id": "node-muqbrxtx-rmwz", "data": {"label": "Ví dụ thực tế", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#8b5cf6"}, "type": "mindmap", "hidden": false, "measured": {"width": 149, "height": 45}, "position": {"x": 640, "y": 2610}}, {"id": "node-muqbrxtx-pge9", "data": {"label": "Kiểm tra định dạng của ảnh", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#8b5cf6"}, "type": "mindmap", "hidden": false, "measured": {"width": 283, "height": 45}, "position": {"x": 960, "y": 2610}}, {"id": "node-muqbrxtx-dp9u", "data": {"label": "Thông thường chúng ta sẽ lấy phần mở rộng trong tên file ảnh (vd: .png, .jpg, ...). Tuy nhiên user cố tình đổi tên 1 file .exe thành .png để đánh lừa hệ thống.\\n⇒ Khi đó ta sẽ đọc Buffer của file đó để kiểm tra", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#8b5cf6"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 210}, "position": {"x": 1280, "y": 2610}}, {"id": "node-muqbrxtx-zqay", "data": {"label": "Tuy nhiên trong thực tế ta ít sử dụng Buffer trực tiếp mà thay vào đó là sử dụng các thư viện để kiểm tra (tuy nhiên bản chất đằng sau thư viện đó thì cũng là sử dụng Buffer)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#8b5cf6"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 183}, "position": {"x": 1600, "y": 2610}}, {"id": "node-muqbrxtx-lvvi", "data": {"label": "Lưu ý quan trọng, khi sử dụng new Buffer hay Buffer.alloc() và Buffer.allocUnsafe()", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#8b5cf6"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 640, "y": 2835}}, {"id": "node-muqbrxtx-kjko", "data": {"label": "new Buffer đã bị khai tử, giờ sử dụng Buffer.allocUnsafe() thay thế.", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#8b5cf6"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 960, "y": 2745}}, {"id": "node-muqbrxtx-brrl", "data": {"label": "Cấp phát bộ nhớ cho Buffer nhưng không xóa dữ liệu cũ trên vùng bộ nhớ được cấp phát", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#8b5cf6"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 1280, "y": 2745}}, {"id": "node-muqbrxtx-uk9q", "data": {"label": "Ưu điểm: nhanh", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#8b5cf6"}, "type": "mindmap", "hidden": false, "measured": {"width": 177, "height": 45}, "position": {"x": 1600, "y": 2700}}, {"id": "node-muqbrxtx-x26v", "data": {"label": "Nhược điểm: dữ liệu cũ trên vùng nhớ mà buffer đươc cấp phát bị rò rỉ", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#8b5cf6"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 100}, "position": {"x": 1600, "y": 2790}}, {"id": "node-muqbrxtx-xn2i", "data": {"label": "Buffer.alloc()", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#8b5cf6"}, "type": "mindmap", "hidden": false, "measured": {"width": 146, "height": 45}, "position": {"x": 960, "y": 2925}}, {"id": "node-muqbrxtx-vds1", "data": {"label": "Cấp phát bộ nhớ cho Buffer đồng thời ghi đè dữ liệu cũ trên vùng bộ nhớ được cấp phát bằng toàn bộ số 0 (zero-fill)", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#8b5cf6"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 1280, "y": 2925}}, {"id": "node-muqbrxtx-2yz2", "data": {"label": "Ưu điểm: Vùng nhớ sạch, tránh rò rỉ dữ liệu cũ", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#8b5cf6"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 1600, "y": 2880}}, {"id": "node-muqbrxtx-dn9z", "data": {"label": "Khuyến điểm: tốc độ chậm hơn 1 chút so với allocUnsafe", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#8b5cf6"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 1600, "y": 2970}}, {"id": "node-muqbrxtx-kql7", "data": {"label": "Stream", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#f97316"}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 45}, "position": {"x": 320, "y": 3105}}, {"id": "node-muqbrxtx-t20g", "data": {"label": "Stream trong NodeJS là gì?", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f97316"}, "type": "mindmap", "hidden": false, "measured": {"width": 278, "height": 45}, "