9u8c", "target": "node-muht5bed-8ufv"}, {"id": "edge-node-muht5bed-9u8c-node-muht5bed-ibi8", "data": {"color": "#ec4899"}, "type": "mindmap", "hidden": true, "source": "node-muht5bed-9u8c", "target": "node-muht5bed-ibi8"}, {"id": "edge-node-muht5bed-9u8c-node-muht5bed-kh64", "data": {"color": "#ec4899"}, "type": "mindmap", "hidden": true, "source": "node-muht5bed-9u8c", "target": "node-muht5bed-kh64"}, {"id": "edge-node-muht5bed-9u8c-node-muht5bed-htqm", "data": {"color": "#ec4899"}, "type": "mindmap", "hidden": true, "source": "node-muht5bed-9u8c", "target": "node-muht5bed-htqm"}, {"id": "edge-node-muht5bed-9u8c-node-muht5bed-tgcx", "data": {"color": "#ec4899"}, "type": "mindmap", "hidden": true, "source": "node-muht5bed-9u8c", "target": "node-muht5bed-tgcx"}, {"id": "edge-node-muht5bed-9u8c-node-muht5bed-4pdh", "data": {"color": "#ec4899"}, "type": "mindmap", "hidden": true, "source": "node-muht5bed-9u8c", "target": "node-muht5bed-4pdh"}, {"id": "edge-node-muht5bed-9u8c-node-muht5bed-hqmr", "data": {"color": "#ec4899"}, "type": "mindmap", "hidden": true, "source": "node-muht5bed-9u8c", "target": "node-muht5bed-hqmr"}, {"id": "edge-node-muht5bed-ycn3-node-mutzsu7o-8ouj", "data": {"color": "#10b981"}, "type": "mindmap", "hidden": false, "source": "node-muht5bed-ycn3", "target": "node-mutzsu7o-8ouj"}, {"id": "edge-node-muht5bed-ycn3-node-mutzv6h5-yibh", "data": {"color": "#10b981"}, "type": "mindmap", "hidden": false, "source": "node-muht5bed-ycn3", "target": "node-mutzv6h5-yibh"}, {"id": "edge-node-muht5bed-rvw1-node-mutzwi0o-998u", "data": {"color": "#10b981"}, "type": "mindmap", "hidden": false, "source": "node-muht5bed-rvw1", "target": "node-mutzwi0o-998u"}, {"id": "edge-node-muht5bed-1iui-node-muu10g1d-ocjc", "data": {"color": "#10b981"}, "type": "mindmap", "hidden": false, "source": "node-muht5bed-1iui", "target": "node-muu10g1d-ocjc"}, {"id": "edge-node-muht5bec-8xnf-node-muvdq5td-fxcm", "data": {"color": "#10b981"}, "type": "mindmap", "hidden": false, "source": "node-muht5bec-8xnf", "target": "node-muvdq5td-fxcm"}], "nodes": [{"id": "root", "data": {"label": "NestJS", "isRoot": true, "collapsed": false, "childCount": 4}, "type": "mindmap", "hidden": false, "measured": {"width": 140, "height": 44}, "position": {"x": 0, "y": 0}}, {"id": "node-muht5bec-lbhc", "data": {"label": "Dependency Injection", "isRoot": false, "collapsed": true, "childCount": 3, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": false, "dragging": false, "measured": {"width": 230, "height": 45}, "position": {"x": 240, "y": -1923}, "selected": false}, {"id": "node-muht5bec-vn7t", "data": {"label": "Là 1 cách triển khai của Inversion of Control (IoC) pattern", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": true, "measured": {"width": 360, "height": 73}, "position": {"x": 520, "y": -811}}, {"id": "node-muht5bec-ocmg", "data": {"label": "Thể hiện qua việc một đối tượng không tự khởi tạo các thành phần mà nó phụ thuộc, thay vào đó nó sẽ tiêm/bơm (inject) từ bên ngoài vào", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": true, "dragging": false, "measured": {"width": 360, "height": 128}, "position": {"x": 930, "y": -811}, "selected": false}, {"id": "node-muht5bec-dfl2", "data": {"label": "// DEPENDENCY INJECTION (DI)\\nclass Order {\\n// private emailService = new EmailService(); // Tight Coupling\\nconstructor(\\nprivate emailService: EmailService // Loose Coupling\\n) {}\\ncreateOrder() {\\nthis.emailService.send();\\n}\\n}\\nclass EmailService {\\nsend() {\\nconsole.log('[Sv1] Send email')\\n}\\n}\\nconst emailService = new EmailService();\\nconst order = new Order(emailService);\\norder.createOrder();", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": true, "dragging": false, "measured": {"width": 360, "height": 623}, "position": {"x": 1340, "y": -811}, "selected": false}, {"id": "node-muht5bec-c185", "data": {"label": "3 thành phần triển khai DI", "isRoot": false, "collapsed": false, "childCount": 3, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": true, "measured": {"width": 269, "height": 45}, "position": {"x": 520, "y": -334.5}}, {"id": "node-muht5bec-fbzx", "data": {"label": "Client (Dependency Consumer) - Lớp sử dụng dịch vụ (vd: OrderService)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": true, "measured": {"width": 360, "height": 100}, "position": {"x": 839, "y": -421.5}, "selected": false}, {"id": "node-muht5bec-nj4v", "data": {"label": "Service (Dependency): Lớp cung cấp dịch vụ (vd: EmailService)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": true, "dragging": false, "measured": {"width": 360, "height": 73}, "position": {"x": 839, "y": -307}, "selected": false}, {"id": "node-muht5bec-z87u", "data": {"label": "Injector: NestJS IoC container", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": true, "dragging": false, "measured": {"width": 300, "height": 45}, "position": {"x": 839, "y": -220}, "selected": false}, {"id": "node-muht5bec-ur0m", "data": {"label": "Ưu điểm", "isRoot": false, "collapsed": false, "childCount": 3, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": true, "measured": {"width": 140, "height": 45}, "position": {"x": 520, "y": 22.5}}, {"id": "node-muht5bec-v5fh", "data": {"label": "Tính linh hoạt: chỉ cần thay đổi logic trong Service (Dependency) thay vì phải thay đổi logic trực tiếp trong Client (Dependency Consumer)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": true, "dragging": false, "measured": {"width": 360, "height": 155}, "position": {"x": 760, "y": -92}, "selected": false}, {"id": "node-muht5bec-jwkc", "data": {"label": "Dễ test", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": true, "dragging": false, "measured": {"width": 140, "height": 45}, "position": {"x": 760.6250001269191, "y": 88.49996774584751}, "selected": false}, {"id": "node-muht5bec-928e", "data": {"label": "Tối ưu RAM - do IoC container quản lý các instances (thường là singleton) thay vì phải tạo mới instance", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#6366f1"}, "type": "mindmap", "hidden": true, "dragging": false, "measured": {"width": 360, "height": 128}, "position": {"x": 760, "y": 150.5}, "selected": false}, {"id": "node-muht5bec-2m4g", "data": {"label": "Module system", "isRoot": false, "collapsed": false, "childCount": 5, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "dragging": false, "measured": {"width": 170, "height": 45}, "position": {"x": 240, "y": -233.5}, "selected": false}, {"id": "node-muht5bec-1ni8", "data": {"label": "Trong NestJS thì module có thể hiểu là đơn vị cấu trúc ứng dụng và cần tối thiểu 1 module để có thể khởi chạy ứng dụng - Root module chính là điểm khởi đầu để NestJS xây dựng bản đồ ứng dụng", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "dragging": false, "measured": {"width": 360, "height": 183}, "position": {"x": 480, "y": -1767.5}, "selected": false}, {"id": "node-muht5bec-taam", "data": {"label": "NestJS sẽ đi từ Root Module (AppModule) nhìn vào mảng imports để tìm các module con, rồi tiếp tục vào module con tìm các module cháu... cho đến khi xây dựng xong toàn bộ hệ thống phụ thuộc", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 210}, "position": {"x": 890, "y": -1767.5}}, {"id": "node-muht5bec-nlwa", "data": {"label": "để định nghĩa 1 module thì sử dụng @Module decorator - nó bao gồm 4 thành phần", "isRoot": false, "collapsed": false, "childCount": 4, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "dragging": false, "measured": {"width": 360, "height": 100}, "position": {"x": 480, "y": -1163.5}, "selected": false}, {"id": "node-muht5bec-8xnf", "data": {"label": "providers: là những providers (services, repository,factory, helper, ...) sẽ được NestJS khởi tạo trọng phạm vi của module này", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "dragging": false, "measured": {"width": 360, "height": 128}, "position": {"x": 890, "y": -1355.5}, "selected": false}, {"id": "node-muht5bec-sxbx", "data": {"label": "Trong NestJS, các provider mặc định là private (thể hiện tính đóng gói - enscapsulation)", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "dragging": false, "measured": {"width": 360, "height": 100}, "position": {"x": 1300, "y": -1474.5}, "selected": false}, {"id": "node-muht5bec-u9zd", "data": {"label": "VD: Nếu bạn khai báo UserService chỉ trong UserModule, thì chỉ có UserController nằm trong cùng module mới có thể gọi tới UserService\\nNếu muốn OrderService có thể sử dụng UserService:\\nTrong UserService phải exports ra UserService\\nTrong OrderModule phải imports UserModule", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "dragging": false, "measured": {"width": 360, "height": 320}, "position": {"x": 1710, "y": -1474.5}, "selected": false}, {"id": "node-muht5bec-kimc", "data": {"label": "controllers: tập hợp các controllers được định nghĩa trong module này cần được khởi tạo", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "dragging": false, "measured": {"width": 360, "height": 100}, "position": {"x": 890, "y": -998.5}, "selected": false}, {"id": "node-muht5bec-jfmo", "data": {"label": "imports: danh sách các modules, cái mà exports ra những providers mà module này cần để sử dụng", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "dragging": false, "measured": {"width": 360, "height": 100}, "position": {"x": 890, "y": -870.5}, "selected": false}, {"id": "node-muht5bec-xl4f", "data": {"label": "exports: danh sách các providers mà module này muốn  xuất ra cho các module khác sử dụng", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "dragging": false, "measured": {"width": 360, "height": 100}, "position": {"x": 890, "y": -742.5}, "selected": false}, {"id": "node-muht5bec-n4mx", "data": {"label": "3 mốc thời gian trong vòng đời NestJS", "isRoot": false, "collapsed": false, "childCount": 3, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "dragging": false, "measured": {"width": 360, "height": 73}, "position": {"x": 480, "y": -417.5}, "selected": false}, {"id": "node-muht5bec-v3o6", "data": {"label": "Compile time (thời gian biên dịch): là khoảng thời gian thực thi lệnh npm run build", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "dragging": false, "measured": {"width": 360, "height": 100}, "position": {"x": 890, "y": -614.5}, "selected": false}, {"id": "node-muht5bec-364i", "data": {"label": "Đây chính là thời gian mà các Module tĩnh được khởi tạo", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "dragging": false, "measured": {"width": 360, "height": 73}, "position": {"x": 1300, "y": -614.5}, "selected": false}, {"id": "node-muht5bec-v5km", "data": {"label": "Boostrap time (thời gian khởi chạy - runtime): là khoảng thời gian thực thi lệnh npm run start", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "dragging": false, "measured": {"width": 360, "height": 100}, "position": {"x": 890, "y": -431.5}, "selected": false}, {"id": "node-muht5bec-8pmc", "data": {"label": "Đây chính là khoảng thời gian mà các Dynamic module được khởi tạo.\\nVì lúc này nodejs app mới chạy trên server và lúc đó nó mới có thể lấy được biến môi trường hoặc đọc file để lấy dữ liệu cái mà cần dùng cho việc config dynamic module", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "dragging": false, "measured": {"width": 360, "height": 210}, "position": {"x": 1300, "y": -431.5}, "selected": false}, {"id": "node-muht5bec-n8e4", "data": {"label": "Request time: là khoảng thời gian sau khi toàn bộ ứng dụng đã khởi động thành công và có thể xử lý cac request từ phía client", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "dragging": false, "measured": {"width": 360, "height": 128}, "position": {"x": 890, "y": -234.5}, "selected": false}, {"id": "node-muht5bec-gab3", "data": {"label": "Lúc này thì cả Module tĩnh và Module động đều cố định, không chỉnh sửa được nữa", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "dragging": false, "measured": {"width": 360, "height": 100}, "position": {"x": 1300, "y": -234.5}, "selected": false}, {"id": "node-muht5bec-i8rs", "data": {"label": "Phân loại module", "isRoot": false, "collapsed": false, "childCount": 3, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "dragging": false, "measured": {"width": 191, "height": 45}, "position": {"x": 480, "y": 77}, "selected": false}, {"id": "node-muht5bec-hart", "data": {"label": "Feature module (module chức năng)", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 73}, "position": {"x": 721, "y": -92.5}}, {"id": "node-muht5bec-utnm", "data": {"label": "dùng để đóng gói code theo từng domain, ví dụ UserModule, ProductModule,...", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "dragging": false, "measured": {"width": 360, "height": 100}, "position": {"x": 1131, "y": -92.5}, "selected": false}, {"id": "node-muht5bec-wvm7", "data": {"label": "Shared module (module dùng chung)", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "dragging": false, "measured": {"width": 360, "height": 73}, "position": {"x": 721, "y": 22}, "selected": false}, {"id": "node-muht5bec-6409", "data": {"label": "dùng cho trường hợp module có nhu cầu dùng lại ở nhiều nơi", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "dragging": false, "measured": {"width": 360, "height": 73}, "position": {"x": 1131, "y": 22}, "selected": false}, {"id": "node-muht5bec-tldd", "data": {"label": "Global module (module toàn cục)", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "dragging": false, "measured": {"width": 336, "height": 45}, "position": {"x": 721, "y": 191.5}, "selected": false}, {"id": "node-muht5bec-wxd2", "data": {"label": "dùng cho trường hợp module được dùng ở toàn bộ (hoặc phần lớn) các nơi trong ứng dụng.\\nSử dụng @Global() decorator để đánh dấu 1 global module và chỉ cần import một lần duy nhất ở Root Module (AppModule)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "dragging": false, "measured": {"width": 360, "height": 210}, "position": {"x": 1107, "y": 191.5}, "selected": false}, {"id": "node-muht5bec-375q", "data": {"label": "Dynamic module", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "dragging": false, "measured": {"width": 186, "height": 45}, "position": {"x": 480, "y": 865}, "selected": false}, {"id": "node-muht5bec-kt1l", "data": {"label": "NestJS cho phép tạo các module có thể cấu hình trong thời gian chạy, hữu ích khi cần cung cấp các module linh hoạt và có thể tùy chỉnh. hay sử dụng như config module (database,  kafka, 3th services...)", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "dragging": false, "measured": {"width": 360, "height": 210}, "position": {"x": 720, "y": 429.5}, "selected": false}, {"id": "node-muht5bec-g8qm", "data": {"label": "1 điểm để nhớ phần này rõ hơn, đó là việc trong quá trình runtime (boostrap time) thì mới đọc được giá trị của các biến môi trường (vd: process.env.DATABASE_CONNECTION,...)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "dragging": false, "measured": {"width": 360, "height": 183}, "position": {"x": 1130, "y": 429.5}, "selected": false}, {"id": "node-muht5bed-shu4", "data": {"label": "3 phương thức để cấu hình một dynamic module", "isRoot": false, "collapsed": false, "childCount": 3, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "dragging": false, "measured": {"width": 360, "height": 73}, "position": {"x": 720, "y": 984}, "selected": false}, {"id": "node-muht5bed-ycn3", "data": {"label": "register(): sử dụng để cấu hình module với các tham số chỉ dành riêng cho module đang import nó\\nVD: UserModule sử dụng JWTModule và setting token expire là 1 ngày, còn AdminModule thì token expire là 7 ngày", "isRoot": false, "collapsed": false, "childCount": 2, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "dragging": false, "measured": {"width": 360, "height": 210}, "position": {"x": 1130, "y": 718}, "selected": false}, {"id": "node-muht5bed-rvw1", "data": {"label": "forRoot(): sử dụng để cấu hình module duy nhất một lần tại Root module (AppModule), thường có phạm vi  @Global.\\nVD: thường sử dụng cho việc kết nối DB, Message broker...", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "dragging": false, "measured": {"width": 360, "height": 183}, "position": {"x": 1130, "y": 993}, "selected": false}, {"id": "node-muht5bed-1iui", "data": {"label": "forFeature(): luôn luôn theo sau forRoot(), sử dụng để cấu hình thêm cho các module con, dựa trên cấu hình tổng của forRoot() đã dựng lên trước đó\\nVD: g/sử forRoot sử dụng để kết nối DB, thì forFeature() sử dụng để chỉ định module này sẽ làm việc với table nào trong DB mà forRoot() đã kết nối .", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "dragging": false, "measured": {"width": 360, "height": 293}, "position": {"x": 1130, "y": 1259}, "selected": false}, {"id": "node-muht5bed-a5wn", "data": {"label": "Injection scopes", "isRoot": false, "collapsed": false, "childCount": 3, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "dragging": false, "measured": {"width": 178, "height": 45}, "position": {"x": 240, "y": 1653}, "selected": false}, {"id": "node-muht5bed-jrdz", "data": {"label": "DEFAULT", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "dragging": false, "measured": {"width": 140, "height": 45}, "position": {"x": 480, "y": 1497.5}, "selected": false}, {"id": "node-muht5bed-l5cw", "data": {"label": "Môi một proivder sẽ chỉ khởi tạo 1 instance duy nhất của nó và được sử dụng chung trong toàn ứng dụng", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "dragging": false, "measured": {"width": 360, "height": 128}, "position": {"x": 720, "y": 1497.5}, "selected": false}, {"id": "node-muht5bed-vo8g", "data": {"label": "Tiết kiệm RAM, khởi động nhanh, performance tốt ⇒ khuyên dùng", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "dragging": false, "measured": {"width": 360, "height": 73}, "position": {"x": 1130, "y": 1497.5}, "selected": false}, {"id": "node-muht5bed-2p6l", "data": {"label": "REQUEST", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "dragging": false, "measured": {"width": 140, "height": 45}, "position": {"x": 480, "y": 1667}, "selected": false}, {"id": "node-muht5bed-i5ny", "data": {"label": "Mỗi một provider sẽ được tạo mới instance của nó khi có 1 request (http) đi vào hệ thống. instance này sẽ được dọn dẹp sau khi hoàn thành xử lý request\\n", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "dragging": false, "measured": {"width": 360, "height": 155}, "position": {"x": 720, "y": 1667}, "selected": false}, {"id": "node-muht5bed-8q8b", "data": {"label": "Cho phép lưu trữ thông tin riêng biệt của từng request (request ID, user jwt token...).\\nTuy nhiên sẽ tốn tài nguyên,  làm giảm hiệu suất ứng dụng", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "dragging": false, "measured": {"width": 360, "height": 155}, "position": {"x": 1130, "y": 1667}, "selected": false}, {"id": "node-muht5bed-8xjk", "data": {"label": "Lưu ý QUAN TRỌNG: Nếu service A (default scope) mà inject service B (request scope) thì service A sẽ bị chuyển thành request scope", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "dragging": false, "measured": {"width": 360, "height": 128}, "position": {"x": 1540, "y": 1667}, "selected": false}, {"id": "node-muht5bed-1sgo", "data": {"label": "TRANSIENT (tạm thời)", "isRoot": false, "collapsed": false, "childCount": 1, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "dragging": false, "measured": {"width": 234, "height": 45}, "position": {"x": 480, "y": 1822.5}, "selected": false}, {"id": "node-muht5bed-husq", "data": {"label": "Mỗi 1 provider được inject vào 1 module thì sẽ được tạo 1 instance mới", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#f59e0b"}, "type": "mindmap", "hidden": false, "dragging": false, "measured": {"width": 360, "height": 100}, "position": {"x": 764, "y": 1822.5}, "selected": false}, {"id": "node-muht5bed-9u8c", "data": {"label": "Request lifecycle", "isRoot": false, "collapsed": true, "childCount": 7, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": false, "dragging": false, "measured": {"width": 183, "height": 45}, "position": {"x": 240, "y": 1923}, "selected": false}, {"id": "node-muht5bed-8ufv", "data": {"label": "Middleware: Xử lý dữ liệu request thô gửi lên. Thường sử dụng cho logging, body parsing, xử lý header...", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": true, "measured": {"width": 360, "height": 128}, "position": {"x": 480, "y": -193.5}}, {"id": "node-muht5bed-ibi8", "data": {"label": "Guard: Kiểm tra quyền truy cập (authen và author)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": true, "measured": {"width": 360, "height": 73}, "position": {"x": 480, "y": -65}}, {"id": "node-muht5bed-kh64", "data": {"label": "Interceptor: Trước khi đi vào handler", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": true, "measured": {"width": 360, "height": 73}, "position": {"x": 480, "y": 36}}, {"id": "node-muht5bed-htqm", "data": {"label": "Pipe: Validate & transform dữ liệu (thường là ép kiểu dữ liệu)", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": true, "measured": {"width": 360, "height": 73}, "position": {"x": 480, "y": 137}}, {"id": "node-muht5bed-tgcx", "data": {"label": "Handler: controller điều phối xử lý nghiệp vụ chính", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": true, "measured": {"width": 360, "height": 73}, "position": {"x": 480, "y": 238}}, {"id": "node-muht5bed-4pdh", "data": {"label": "Interceptor: Sau khi Handler (controller) trả về dữ liệu", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": true, "measured": {"width": 360, "height": 73}, "position": {"x": 480, "y": 339}}, {"id": "node-muht5bed-hqmr", "data": {"label": "Exception filter: Xử lý lỗi gặp tại bất kỳ quá trình nào", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#ec4899"}, "type": "mindmap", "hidden": true, "measured": {"width": 360, "height": 73}, "position": {"x": 480, "y": 440}}, {"id": "node-mutzsu7o-8ouj", "data": {"label": "register(): là phương thức đồng bộ, dùng cho trường hợp biết chắc chắn giá trị cấu hình ngay tại thời điểm viết code", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "measured": {"width": 360, "height": 128}, "position": {"x": 1540, "y": 626.5}, "selected": false}, {"id": "node-mutzv6h5-yibh", "data": {"label": "registerAsync(): là phương thức bất đồng bộ, dùng cho trường hợp phải lấy các giá trị cấu hình thông qua việc đọc file hoặc lấy từ biến môi trường", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "hidden": false, "dragging": false, "measured": {"width": 360, "height": 155}, "position": {"x": 1540, "y": 796}, "selected": false}, {"id": "node-mutzwi0o-998u", "data": {"label": "forRoot() và forRootAsync(): sự khác biệt tương tự như như register() và registerAsync()", "isRoot": false, "collapsed": false, "childCount": 0, "branchColor": "#10b981"}, "type": "mindmap", "h